import React, { useState, useMemo, useEffect } from 'react';
import type { Item, Transaction } from './types';
import AddItemModal from './components/AddItemModal';
import ItemDetailModal from './components/ItemDetailModal';
import { PlusIcon, BoxIcon, SearchIcon, TrashIcon, DownloadIcon } from './components/icons';

const STORAGE_KEY = 'inventory_system_data_v2';
const ADMIN_PASSWORD = '0000';
const PRODUCT_ONLY_PASSWORD = '1111';

// 고유 ID 생성을 위한 유틸리티
const generateId = (prefix: string) => `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

const calculateStock = (item: Item): number => {
  return item.transactions.reduce((acc, t) => {
    return t.type === 'purchase' ? acc + t.quantity : acc - t.quantity;
  }, 0);
};

const App: React.FC = () => {
  // 인증 상태
  const [authRole, setAuthRole] = useState<'admin' | 'product_only' | null>(null);
  const [loginPassword, setLoginPassword] = useState('');
  const [activeTab, setActiveTab] = useState<'part' | 'product'>('part');

  // LocalStorage에서 초기 데이터 로드
  const [items, setItems] = useState<Item[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      const data = saved ? JSON.parse(saved) : [];
      return data.map((item: any) => ({ ...item, type: item.type || 'part' }));
    } catch (e) {
      console.error("Failed to load data", e);
      return [];
    }
  });

  const [showAddItemModal, setShowAddItemModal] = useState(false);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // 삭제 관련 상태
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [deletePassword, setDeletePassword] = useState('');

  // 데이터 변경 시 LocalStorage에 자동 저장
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  }, [items]);

  // 권한에 따른 탭 초기화
  useEffect(() => {
    if (authRole === 'product_only') {
      setActiveTab('product');
    } else if (authRole === 'admin') {
      setActiveTab('part');
    }
  }, [authRole]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginPassword === ADMIN_PASSWORD) {
      setAuthRole('admin');
    } else if (loginPassword === PRODUCT_ONLY_PASSWORD) {
      setAuthRole('product_only');
    } else {
      alert('비밀번호가 틀렸습니다.');
    }
    setLoginPassword('');
  };

  const handleLogout = () => {
    setAuthRole(null);
    setSearchTerm('');
  };

  // ID를 기반으로 선택된 아이템을 항상 최신 상태로 유지
  const selectedItem = useMemo(() => 
    items.find(item => item.id === selectedItemId) || null
  , [items, selectedItemId]);

  const handleAddItem = (itemData: Omit<Item, 'id' | 'transactions'>, initialQuantity: number) => {
    const newItem: Item = {
      ...itemData,
      id: generateId('item'),
      transactions: [],
    };
    if (initialQuantity > 0) {
      newItem.transactions.push({
        id: generateId('t'),
        type: 'purchase',
        quantity: initialQuantity,
        date: new Date().toISOString(),
        remarks: '초기 수량 등록',
      });
    }
    setItems(prevItems => [newItem, ...prevItems]);
  };

  const handleUpdateItem = (itemId: string, updatedData: Partial<Item>) => {
    setItems(prevItems =>
      prevItems.map(item => (item.id === itemId ? { ...item, ...updatedData } : item))
    );
  };

  const handleAddTransaction = (itemId: string, transaction: Omit<Transaction, 'id'>) => {
    setItems(prevItems =>
      prevItems.map(item => {
        if (item.id === itemId) {
          return {
            ...item,
            transactions: [...item.transactions, { ...transaction, id: generateId('t') }],
          };
        }
        return item;
      })
    );
  };

  const handleUpdateTransaction = (itemId: string, transactionId: string, updatedData: Partial<Transaction>) => {
    setItems(prevItems =>
      prevItems.map(item => {
        if (item.id === itemId) {
          return {
            ...item,
            transactions: item.transactions.map(t => t.id === transactionId ? { ...t, ...updatedData } : t)
          };
        }
        return item;
      })
    );
  };

  const handleDeleteTransaction = (itemId: string, transactionId: string) => {
    setItems(prevItems =>
      prevItems.map(item => {
        if (item.id === itemId) {
          return {
            ...item,
            transactions: item.transactions.filter(t => t.id !== transactionId)
          };
        }
        return item;
      })
    );
  };

  const handleDeleteItem = () => {
    const currentPass = authRole === 'admin' ? ADMIN_PASSWORD : PRODUCT_ONLY_PASSWORD;
    if (deletePassword !== currentPass) {
      alert('비밀번호가 틀렸습니다.');
      return;
    }

    if (itemToDelete) {
      setItems(prevItems => prevItems.filter(item => item.id !== itemToDelete));
      if (selectedItemId === itemToDelete) {
        setSelectedItemId(null);
      }
      setItemToDelete(null);
      setDeletePassword('');
      alert('품목이 성공적으로 삭제되었습니다.');
    }
  };

  const filteredItems = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return items.filter(item => {
        const matchesTab = item.type === activeTab;
        const matchesSearch = 
            item.name.toLowerCase().includes(term) ||
            item.code.toLowerCase().includes(term) ||
            (item.drawingNumber && item.drawingNumber.toLowerCase().includes(term)) ||
            item.transactions.some(t => t.serialNumber && t.serialNumber.toLowerCase().includes(term));
        return matchesTab && matchesSearch;
    });
  }, [items, searchTerm, activeTab]);

  const existingCodes = useMemo(() => items.map(item => item.code), [items]);

  const allUsedSerials = useMemo(() => {
    return items.flatMap(item => 
      item.transactions.map(t => t.serialNumber).filter((s): s is string => !!s)
    );
  }, [items]);

  const stats = useMemo(() => {
    const partItems = items.filter(i => i.type === 'part');
    const productItems = items.filter(i => i.type === 'product');
    return {
      partCount: partItems.length,
      productCount: productItems.length,
      partStock: partItems.reduce((sum, i) => sum + calculateStock(i), 0),
      productStock: productItems.reduce((sum, i) => sum + calculateStock(i), 0),
    };
  }, [items]);

  // 엑셀 내보내기 함수
  const exportToExcel = () => {
    const itemsToExport = items.filter(item => item.type === activeTab);
    if (itemsToExport.length === 0) {
      alert('내보낼 데이터가 없습니다.');
      return;
    }

    let csvContent = "\ufeff"; // UTF-8 BOM
    const headers = activeTab === 'part' 
      ? ['코드', '품명', '도번', '현재재고', '등록일', '비고']
      : ['코드', '제품명', '현재재고', '등록일', '비고'];

    csvContent += headers.join(',') + '\r\n';

    itemsToExport.forEach(item => {
      const stock = calculateStock(item);
      const row = activeTab === 'part'
        ? [item.code, item.name, item.drawingNumber || '', stock, item.registrationDate, item.remarks || '']
        : [item.code, item.name, stock, item.registrationDate, item.remarks || ''];

      const escapedRow = row.map(val => `"${String(val).replace(/"/g, '""')}"`);
      csvContent += escapedRow.join(',') + '\r\n';
    });

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    const dateStr = new Date().toISOString().split('T')[0];
    const fileName = `${activeTab === 'part' ? '부품' : '제품'}_재고리스트_${dateStr}.csv`;

    link.setAttribute('href', url);
    link.setAttribute('download', fileName);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // 로그인 화면 렌더링
  if (!authRole) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md p-10 animate-fade-in-up border border-slate-100">
          <div className="flex flex-col items-center mb-10">
            <div className="bg-indigo-600 p-4 rounded-2xl shadow-lg mb-6">
              <BoxIcon className="w-10 h-10 text-white" />
            </div>
            <h1 className="text-2xl font-black text-slate-800 tracking-tight uppercase">재고 관리 로그인</h1>
            <p className="text-slate-400 text-sm font-medium mt-2">시스템 접속을 위해 비밀번호를 입력하세요</p>
          </div>
          <form onSubmit={handleLogin} className="space-y-6">
            <input 
              type="password" 
              autoFocus
              value={loginPassword}
              onChange={(e) => setLoginPassword(e.target.value)}
              placeholder="PASSWORD"
              className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-600 outline-none text-center text-3xl font-black tracking-[0.5em] transition-all"
            />
            <button 
              type="submit" 
              className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95"
            >
              로그인
            </button>
          </form>
          <div className="mt-10 text-center">
            <p className="text-[10px] text-slate-300 font-bold uppercase tracking-widest">Inventory Management System Access Control</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 font-sans">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10 shadow-sm">
        <div className="container mx-auto px-4 sm:px-6">
            <div className="flex justify-between items-center py-4">
                <div className="flex items-center space-x-3">
                    <BoxIcon className="h-7 w-7 text-indigo-600" />
                    <h1 className="text-xl font-bold text-slate-900 tracking-tight uppercase">재고 관리 시스템</h1>
                </div>
                <div className="flex items-center space-x-6 text-sm">
                  {authRole === 'admin' && (
                    <div className="text-right">
                        <p className="text-slate-400 text-[10px] uppercase font-bold">Parts In Stock</p>
                        <p className="font-bold text-slate-700">{stats.partStock.toLocaleString()} EA</p>
                    </div>
                  )}
                  <div className="text-right">
                      <p className="text-slate-400 text-[10px] uppercase font-bold">Products In Stock</p>
                      <p className="font-bold text-indigo-600">{stats.productStock.toLocaleString()} EA</p>
                  </div>
                  <button 
                    onClick={handleLogout}
                    className="ml-4 px-3 py-1 bg-slate-100 text-slate-500 rounded-md hover:bg-slate-200 transition-colors font-bold text-xs uppercase"
                  >
                    Logout
                  </button>
                </div>
            </div>
            {/* 탭 네비게이션 */}
            <div className="flex space-x-8 -mb-px">
                {authRole === 'admin' && (
                  <button 
                    onClick={() => setActiveTab('part')}
                    className={`pb-3 px-1 text-sm font-black uppercase tracking-widest transition-all border-b-2 ${activeTab === 'part' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
                  >
                    부품 재고관리 ({stats.partCount})
                  </button>
                )}
                <button 
                  onClick={() => setActiveTab('product')}
                  className={`pb-3 px-1 text-sm font-black uppercase tracking-widest transition-all border-b-2 ${activeTab === 'product' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
                >
                  제품 재고관리 ({stats.productCount})
                </button>
            </div>
        </div>
      </header>

      <main className="container mx-auto p-4 sm:p-6">
        <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4 mb-6">
          <div className="relative flex-grow max-w-md">
              <span className="absolute inset-y-0 left-0 flex items-center pl-3">
                  <SearchIcon className="text-slate-400 w-4 h-4" />
              </span>
              <input
                  type="text"
                  placeholder={`${activeTab === 'part' ? '부품' : '제품'}명, 코드, 일련번호 검색...`}
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value.toUpperCase())}
                  className="w-full pl-9 pr-4 py-2.5 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 bg-white shadow-sm font-medium"
              />
          </div>
          <div className="flex gap-2">
            <button
                onClick={exportToExcel}
                className="flex items-center justify-center gap-2 px-6 py-2.5 bg-emerald-600 text-white font-bold rounded-lg shadow hover:bg-emerald-700 transition-all w-full sm:w-auto text-sm"
            >
                <DownloadIcon className="w-4 h-4" />
                <span>엑셀 내보내기</span>
            </button>
            <button
                onClick={() => setShowAddItemModal(true)}
                className="flex items-center justify-center gap-2 px-6 py-2.5 bg-indigo-600 text-white font-bold rounded-lg shadow hover:bg-indigo-700 transition-all w-full sm:w-auto text-sm"
            >
                <PlusIcon className="w-5 h-5" />
                <span>신규 {activeTab === 'part' ? '부품' : '제품'} 등록</span>
            </button>
          </div>
        </div>

        <div className="bg-white shadow-xl border border-slate-200 rounded-xl overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead className="text-[11px] text-slate-500 uppercase bg-slate-50/80 border-b border-slate-100 font-black">
                <tr>
                  <th scope="col" className="px-6 py-4">코드</th>
                  <th scope="col" className="px-6 py-4">{activeTab === 'part' ? '품명' : '제품명'}</th>
                  {activeTab === 'part' && <th scope="col" className="px-6 py-4">도번</th>}
                  <th scope="col" className="px-6 py-4 text-right">현재 재고</th>
                  <th scope="col" className="px-6 py-4 text-center">작업</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredItems.length > 0 ? (
                  filteredItems.map(item => {
                    const stock = calculateStock(item);
                    return (
                      <tr key={item.id} className="hover:bg-indigo-50/50 transition-colors group">
                        <td className="px-6 py-4 font-mono text-xs text-indigo-600 font-bold">{item.code}</td>
                        <td className="px-6 py-4 font-bold text-slate-800 uppercase">{item.name}</td>
                        {activeTab === 'part' && (
                          <td className="px-6 py-4 text-slate-500 font-mono text-xs">{item.drawingNumber || '-'}</td>
                        )}
                        <td className="px-6 py-4 text-right font-black">
                          <span className={`text-base ${stock > 0 ? 'text-slate-900' : 'text-rose-500'}`}>
                              {stock.toLocaleString()}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <div className="flex items-center justify-center gap-2">
                            <button 
                              onClick={() => setSelectedItemId(item.id)} 
                              className="px-4 py-2 text-xs font-bold text-indigo-600 bg-indigo-50 rounded-md hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
                            >
                              상세보기
                            </button>
                            <button 
                              onClick={() => setItemToDelete(item.id)}
                              className="p-2 text-rose-400 hover:text-rose-600 hover:bg-rose-50 rounded-md transition-all"
                              title="삭제"
                            >
                              <TrashIcon className="w-4 h-4" />
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })
                ) : (
                  <tr>
                    <td colSpan={activeTab === 'part' ? 5 : 4} className="text-center py-24">
                        <BoxIcon className="w-16 h-16 text-slate-100 mx-auto mb-4" />
                        <p className="text-slate-400 text-sm font-bold uppercase tracking-widest">해당 카테고리에 데이터가 없습니다</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </main>

      {/* 삭제 비밀번호 모달 */}
      {itemToDelete && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-[60] flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl p-8 max-w-sm w-full shadow-2xl border border-slate-100 animate-fade-in-up">
                <h4 className="text-lg font-black text-slate-800 mb-2">품목 삭제 인증</h4>
                <p className="text-sm text-slate-500 mb-6 font-medium">품목을 삭제하려면 비밀번호를 입력하세요.</p>
                <input 
                    type="password" 
                    autoFocus
                    value={deletePassword}
                    onChange={(e) => setDeletePassword(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleDeleteItem()}
                    placeholder="비밀번호"
                    className="w-full px-4 py-3 border-2 border-slate-100 rounded-xl focus:border-indigo-500 outline-none mb-4 text-center text-xl font-bold tracking-widest"
                />
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => { setItemToDelete(null); setDeletePassword(''); }} className="py-3 bg-slate-100 text-slate-600 rounded-xl font-bold hover:bg-slate-200 transition-all">취소</button>
                    <button onClick={handleDeleteItem} className="py-3 bg-rose-600 text-white rounded-xl font-bold hover:bg-rose-700 shadow-lg shadow-rose-200 transition-all">삭제 확정</button>
                </div>
            </div>
        </div>
      )}

      {showAddItemModal && (
        <AddItemModal 
          onAddItem={handleAddItem} 
          onClose={() => setShowAddItemModal(false)} 
          existingCodes={existingCodes}
          defaultType={activeTab}
        />
      )}
      {selectedItem && (
        <ItemDetailModal 
          item={selectedItem} 
          authRole={authRole}
          allUsedSerials={allUsedSerials}
          onAddTransaction={handleAddTransaction}
          onUpdateTransaction={handleUpdateTransaction}
          onDeleteTransaction={handleDeleteTransaction}
          onUpdateItem={handleUpdateItem}
          onClose={() => setSelectedItemId(null)} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import type { Item, Transaction } from '../types';
import { CloseIcon, ArrowUpIcon, ArrowDownIcon, EditIcon, CheckIcon, BoxIcon, TrashIcon } from './icons';

interface ItemDetailModalProps {
  item: Item;
  authRole: 'admin' | 'product_only';
  allUsedSerials: string[];
  onAddTransaction: (itemId: string, transaction: Omit<Transaction, 'id'>) => void;
  onUpdateTransaction: (itemId: string, transactionId: string, updatedData: Partial<Transaction>) => void;
  onDeleteTransaction: (itemId: string, transactionId: string) => void;
  onUpdateItem: (itemId: string, updatedData: Partial<Item>) => void;
  onClose: () => void;
}

const ADMIN_PASSWORD = '0000';
const PRODUCT_ONLY_PASSWORD = '1111';

/**
 * 일련번호 범위 파싱 함수
 * 예: "AJP00001~00005" -> ["AJP00001", "AJP00002", "AJP00003", "AJP00004", "AJP00005"]
 */
const parseSerialRange = (input: string): string[] => {
  const rangeMatch = input.match(/^(.+?)(\d+)\s*~\s*(.+?)?(\d+)$/);
  if (!rangeMatch) return [input.trim()];

  const prefix = rangeMatch[1];
  const startNumStr = rangeMatch[2];
  const endNumStr = rangeMatch[4];

  const startNum = parseInt(startNumStr, 10);
  const endNum = parseInt(endNumStr, 10);

  if (isNaN(startNum) || isNaN(endNum) || startNum > endNum) return [input.trim()];

  if (endNum - startNum >= 100) {
    throw new Error('일련번호 범위는 한 번에 최대 100개까지 입력 가능합니다.');
  }

  const results: string[] = [];
  const padLength = startNumStr.length;

  for (let i = startNum; i <= endNum; i++) {
    const paddedNum = i.toString().padStart(padLength, '0');
    results.push(`${prefix}${paddedNum}`);
  }

  return results;
};

const ItemDetailModal: React.FC<ItemDetailModalProps> = ({ 
  item, 
  authRole,
  allUsedSerials,
  onAddTransaction, 
  onUpdateTransaction,
  onDeleteTransaction,
  onUpdateItem, 
  onClose 
}) => {
  const [transactionType, setTransactionType] = useState<'purchase' | 'release'>('purchase');
  const [quantity, setQuantity] = useState('');
  const [transRemarks, setTransRemarks] = useState('');
  const [transModelName, setTransModelName] = useState('');
  const [transUserId, setTransUserId] = useState('');
  const [serialNumber, setSerialNumber] = useState('');
  const [customerName, setCustomerName] = useState('');
  const [address, setAddress] = useState('');
  const [phoneNumber, setPhoneNumber] = useState('');

  const [isEditing, setIsEditing] = useState(false);

  const [editingTransactionId, setEditingTransactionId] = useState<string | null>(null);
  const [transEditData, setTransEditData] = useState<Partial<Transaction>>({});

  const [showPasswordInput, setShowPasswordInput] = useState<{
    type: 'item' | 'trans_save' | 'trans_delete';
    targetId?: string;
  } | null>(null);
  const [password, setPassword] = useState('');
  const [editFormData, setEditFormData] = useState<Partial<Item>>({});

  useEffect(() => {
    setEditFormData({
      name: item.name,
      code: item.code,
      modelName: item.modelName,
      application: item.application,
      drawingNumber: item.drawingNumber,
      remarks: item.remarks,
      registrationDate: item.registrationDate
    });
  }, [item]);

  const currentStock = useMemo(() => {
    return item.transactions.reduce((acc, t) => {
      return t.type === 'purchase' ? acc + t.quantity : acc - t.quantity;
    }, 0);
  }, [item.transactions]);

  const isSerialDuplicate = useMemo(() => {
    if (!serialNumber.trim() || serialNumber.includes('~')) return false;
    return allUsedSerials.includes(serialNumber.toUpperCase());
  }, [serialNumber, allUsedSerials]);

  const handleAddTransaction = (e: React.FormEvent) => {
    e.preventDefault();

    let targetSerials: string[] = [serialNumber.toUpperCase().trim()];
    let isRange = false;

    if (item.type === 'product' && serialNumber.includes('~')) {
      try {
        targetSerials = parseSerialRange(serialNumber.toUpperCase());
        isRange = true;
      } catch (err: any) {
        alert(err.message);
        return;
      }
    }

    const duplicates = targetSerials.filter(s => !!s && allUsedSerials.includes(s));
    if (duplicates.length > 0) {
      alert(`다음 일련번호가 이미 존재합니다:\n${duplicates.slice(0, 5).join(', ')}...`);
      return;
    }

    const count = isRange ? targetSerials.length : (parseInt(quantity, 10) || 0);

    if (count <= 0) {
      alert('유효한 수량을 입력하세요.');
      return;
    }

    if (transactionType === 'release' && count > currentStock) {
        alert('출고 수량이 현재 재고보다 많을 수 없습니다.');
        return;
    }

    if (isRange) {
      targetSerials.forEach(s => {
        onAddTransaction(item.id, {
          type: transactionType,
          quantity: 1,
          date: new Date().toISOString(),
          remarks: transRemarks.toUpperCase(),
          modelName: transModelName.toUpperCase(),
          userId: transUserId, // 대문자 변환 제거
          serialNumber: s,
          customerName: customerName,
          address: address,
          phoneNumber: phoneNumber,
        });
      });
      alert(`${targetSerials.length}건의 기록이 등록되었습니다.`);
    } else {
      onAddTransaction(item.id, {
        type: transactionType,
        quantity: count,
        date: new Date().toISOString(),
        remarks: transRemarks.toUpperCase(),
        modelName: transModelName.toUpperCase(),
        userId: transUserId, // 대문자 변환 제거
        serialNumber: item.type === 'product' ? serialNumber.toUpperCase() : '',
        customerName: item.type === 'product' ? customerName : '',
        address: item.type === 'product' ? address : '',
        phoneNumber: item.type === 'product' ? phoneNumber : '',
      });
    }

    setQuantity('');
    setTransRemarks('');
    setTransModelName('');
    setTransUserId('');
    setSerialNumber('');
    setCustomerName('');
    setAddress('');
    setPhoneNumber('');
  };

  const handleActionConfirm = () => {
    const requiredPass = authRole === 'admin' ? ADMIN_PASSWORD : PRODUCT_ONLY_PASSWORD;
    if (password !== requiredPass) {
        alert('비밀번호가 틀렸습니다.');
        return;
    }
    const currentAction = showPasswordInput;
    setPassword('');
    setShowPasswordInput(null);

    if (currentAction?.type === 'item') {
        onUpdateItem(item.id, editFormData);
        setIsEditing(false);
    } else if (currentAction?.type === 'trans_save' && currentAction.targetId) {
        onUpdateTransaction(item.id, currentAction.targetId, transEditData);
        setEditingTransactionId(null);
    } else if (currentAction?.type === 'trans_delete' && currentAction.targetId) {
        onDeleteTransaction(item.id, currentAction.targetId);
    }
  };

  const handleToggleEdit = () => {
    if (isEditing) {
        if (!editFormData.name || !editFormData.code) {
          alert('품명과 코드는 필수입니다.');
          return;
        }
        setShowPasswordInput({ type: 'item' });
    } else {
        setIsEditing(true);
    }
  };

  const handleEditTransaction = (t: Transaction) => {
    setEditingTransactionId(t.id);
    setTransEditData({ ...t });
  };

  const handleTransEditChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    // userId는 대문자 강제 변환에서 제외
    const processedValue = (name === 'quantity') ? (parseInt(value, 10) || 0) : (name === 'userId' ? value : value.toUpperCase());
    setTransEditData(prev => ({ ...prev, [name]: processedValue }));
  };

  const handleSaveTransEdit = (tId: string) => {
    setShowPasswordInput({ type: 'trans_save', targetId: tId });
  };

  const handleDeleteTrans = (tId: string) => {
    setShowPasswordInput({ type: 'trans_delete', targetId: tId });
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex justify-center items-center z-50 p-4">
