                    <div>
                        <label className="block text-[10px] uppercase font-black text-slate-400 mb-1">품명</label>
                        <input name="name" value={editFormData.name || ''} onChange={(e) => setEditFormData({...editFormData, name: e.target.value.toUpperCase()})} className="w-full px-3 py-2 border-2 border-indigo-100 bg-indigo-50/30 rounded-lg text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
                    </div>
                    <div>
                        <label className="block text-[10px] uppercase font-black text-slate-400 mb-1">코드</label>
                        <input name="code" value={editFormData.code || ''} onChange={(e) => setEditFormData({...editFormData, code: e.target.value.toUpperCase()})} className="w-full px-3 py-2 border-2 border-indigo-100 bg-indigo-50/30 rounded-lg text-sm font-mono font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
                    </div>
                    {item.type === 'part' && (
                      <div>
                          <label className="block text-[10px] uppercase font-black text-slate-400 mb-1">도번</label>
                          <input name="drawingNumber" value={editFormData.drawingNumber || ''} onChange={(e) => setEditFormData({...editFormData, drawingNumber: e.target.value.toUpperCase()})} className="w-full px-3 py-2 border-2 border-indigo-100 bg-indigo-50/30 rounded-lg text-sm font-mono font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
                      </div>
                    )}
                    <div>
                        <label className="block text-[10px] uppercase font-black text-slate-400 mb-1">비고</label>
                        <textarea name="remarks" value={editFormData.remarks || ''} onChange={(e) => setEditFormData({...editFormData, remarks: e.target.value.toUpperCase()})} rows={2} className="w-full px-3 py-2 border-2 border-indigo-100 bg-indigo-50/30 rounded-lg text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500" />
                    </div>
                </div>
              ) : (
                <>
                  <h3 className="text-2xl font-black text-slate-800 mb-4 break-all leading-tight uppercase tracking-tight">{item.name}</h3>
                  <div className="space-y-3 text-sm">
                    <div className="flex justify-between border-b border-slate-200/50 pb-2">
                      <span className="text-slate-400 font-bold uppercase text-[10px]">Code</span>
                      <span className="font-mono font-bold text-indigo-600">{item.code}</span>
                    </div>
                    {item.type === 'part' && (
                      <div className="flex justify-between border-b border-slate-200/50 pb-2">
                        <span className="text-slate-400 font-bold uppercase text-[10px]">Drawing No</span>
                        <span className="font-mono font-bold text-slate-500 uppercase">{item.drawingNumber || '-'}</span>
                      </div>
                    )}
                    <div className="flex justify-between">
                      <span className="text-slate-400 font-bold uppercase text-[10px]">Reg Date</span>
                      <span className="font-bold text-slate-500">{item.registrationDate}</span>
                    </div>
                    {item.remarks && (
                      <div className="mt-4 p-3 bg-white rounded-xl border border-slate-100 text-slate-600 font-medium leading-relaxed italic">
                        {item.remarks}
                      </div>
                    )}
                  </div>
                </>
              )}
              <div className="mt-8 pt-6 border-t border-slate-200">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Stock Level</p>
                <p className="text-4xl font-black text-slate-900 leading-none">
                  {currentStock.toLocaleString()} <span className="text-lg text-slate-400 font-bold">EA</span>
                </p>
              </div>
            </div>

            {!isEditing && (
              <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm space-y-4">
                  <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest">신규 수불 등록</h3>
                  <form onSubmit={handleAddTransaction} className="space-y-4">
                      <div className="flex p-1 bg-slate-100 rounded-xl">
                          <button type="button" onClick={() => setTransactionType('purchase')} className={`flex-1 py-2 text-xs font-black rounded-lg transition-all ${transactionType === 'purchase' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>입고</button>
                          <button type="button" onClick={() => setTransactionType('release')} className={`flex-1 py-2 text-xs font-black rounded-lg transition-all ${transactionType === 'release' ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>출고</button>
                      </div>
                      <div className="space-y-2">
                        {item.type === 'product' ? (
                          <>
                            <div className="grid grid-cols-1 gap-2">
                              <div className="relative">
                                <input 
                                  type="text" 
                                  value={serialNumber} 
                                  onChange={(e) => setSerialNumber(e.target.value.toUpperCase())} 
                                  placeholder="일련번호 (예: SN001~005)" 
                                  className={`w-full px-3 py-2 text-sm border-2 rounded-lg font-bold outline-none focus:ring-2 focus:ring-indigo-500 ${isSerialDuplicate ? 'border-rose-400 bg-rose-50' : 'border-slate-200'}`} 
                                />
                                {isSerialDuplicate && <p className="text-[9px] text-rose-500 font-black mt-1 uppercase">이미 등록된 번호입니다</p>}
                              </div>
                            </div>
                            <div className="grid grid-cols-2 gap-2">
                                <input type="number" value={serialNumber.includes('~') ? '' : quantity} disabled={serialNumber.includes('~')} onChange={(e) => setQuantity(e.target.value)} placeholder={serialNumber.includes('~') ? "범위 자동계산" : "수량 (EA) *"} min="1" required={!serialNumber.includes('~')} className="w-full px-3 py-2 text-sm border border-slate-200 rounded-lg font-bold outline-none focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-50" />
                                <input type="text" value={customerName} onChange={(e) => setCustomerName(e.target.value)} placeholder="이름" className="w-full px-3 py-2 text-sm border border-slate-200 rounded-lg font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
                            </div>
                            <div className="grid grid-cols-2 gap-2">
                                <input type="text" value={transUserId} onChange={(e) => setTransUserId(e.target.value)} placeholder="아이디" className="w-full px-3 py-2 text-sm border border-slate-200 rounded-lg font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
                                <input type="text" value={phoneNumber} onChange={(e) => setPhoneNumber(e.target.value)} placeholder="전화번호" className="w-full px-3 py-2 text-sm border border-slate-200 rounded-lg font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
                            </div>
                            <input type="text" value={address} onChange={(e) => setAddress(e.target.value)} placeholder="주소" className="w-full px-3 py-2 text-sm border border-slate-200 rounded-lg font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
                          </>
                        ) : (
                          <div className="grid grid-cols-2 gap-2">
                            <input type="number" value={quantity} onChange={(e) => setQuantity(e.target.value)} placeholder="수량 (EA) *" min="1" required className="w-full px-3 py-2 text-sm border border-slate-200 rounded-lg font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
                            <input type="text" value={transModelName} onChange={(e) => setTransModelName(e.target.value.toUpperCase())} placeholder="기종" className="w-full px-3 py-2 text-sm border border-slate-200 rounded-lg font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
                          </div>
                        )}
                        <input type="text" value={transRemarks} onChange={(e) => setTransRemarks(e.target.value.toUpperCase())} placeholder="사유 / 비고" className="w-full px-3 py-2 text-sm border border-slate-200 rounded-lg font-medium outline-none focus:ring-2 focus:ring-indigo-500" />
                      </div>
                      <button type="submit" className={`w-full py-3 text-white text-sm font-black rounded-xl shadow-lg transition-all active:scale-95 ${transactionType === 'purchase' ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-rose-600 hover:bg-rose-700'}`}>
                          기록 저장
                      </button>
                  </form>
              </div>
            )}
          </div>

          <div className="lg:col-span-3 flex flex-col">
            <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-4">입출고 히스토리</h3>
            <div className="flex-grow border border-slate-100 rounded-2xl overflow-hidden bg-slate-50/50">
                <div className="h-full max-h-[calc(90vh-180px)] overflow-y-auto">
                    {item.transactions.length === 0 ? (
                        <div className="flex flex-col items-center justify-center h-full p-12 opacity-30">
                            <BoxIcon className="w-12 h-12 mb-2" />
                            <p className="text-xs font-bold uppercase tracking-widest">기록 없음</p>
                        </div>
                    ) : (
                        <div className="overflow-x-auto">
                          <table className="w-full text-left text-xs">
                            <thead className="bg-white border-b border-slate-100 text-[10px] font-black uppercase text-slate-400 sticky top-0 z-10">
                              <tr>
                                <th className="px-4 py-3">날짜/구분</th>
                                <th className="px-4 py-3">수량</th>
                                {item.type === 'part' && <th className="px-4 py-3">기종</th>}
                                {item.type === 'product' && (
                                  <>
                                    <th className="px-4 py-3">아이디</th>
                                    <th className="px-4 py-3">일련번호</th>
                                    <th className="px-4 py-3">대상자(이름/번호)</th>
                                    <th className="px-4 py-3">주소</th>
                                  </>
                                )}
                                <th className="px-4 py-3">비고</th>
                                <th className="px-4 py-3 text-center">작업</th>
                              </tr>
                            </thead>
                            <tbody className="divide-y divide-white">
                                {[...item.transactions].reverse().map(t => (
                                    <tr key={t.id} className={`hover:bg-white transition-all group ${editingTransactionId === t.id ? 'bg-indigo-50' : ''}`}>
                                        <td className="px-4 py-3">
                                          <div className="flex items-center gap-2">
                                            <div className={`p-1 rounded ${t.type === 'purchase' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                                              {t.type === 'purchase' ? <ArrowUpIcon className="w-3 h-3"/> : <ArrowDownIcon className="w-3 h-3"/>}
