                                              <input name="modelName" value={transEditData.modelName || ''} onChange={handleTransEditChange} className="w-24 px-2 py-1 border rounded bg-white" />
                                            ) : (
                                              <span className="font-bold text-slate-600">{t.modelName || '-'}</span>
                                            )}
                                          </td>
                                        )}

                                        {item.type === 'product' && (
                                          <>
                                            <td className="px-4 py-3">
