                                              )}
                                            </td>
                                            <td className="px-4 py-3">
                                              {editingTransactionId === t.id ? (
                                                <input name="serialNumber" value={transEditData.serialNumber || ''} onChange={handleTransEditChange} className="w-24 px-2 py-1 border rounded bg-white uppercase" />
                                              ) : (
                                                <span className="font-mono font-bold text-slate-500">{t.serialNumber || '-'}</span>
                                              )}
                                            </td>
                                            <td className="px-4 py-3">
                                              {editingTransactionId === t.id ? (
