import React, { useState, useMemo, useEffect, useRef } from 'react';
import type { Item, Transaction } from './types';
import AddItemModal from './components/AddItemModal';
import ItemDetailModal from './components/ItemDetailModal';
import { PlusIcon, BoxIcon, SearchIcon, TrashIcon, DownloadIcon, CloudIcon, SettingsIcon, CloseIcon } from './components/icons';

const STORAGE_KEY = 'inventory_system_data_v2';
const DRIVE_CONFIG_KEY = 'inventory_drive_config';
const ADMIN_PASSWORD = '0000';
const PRODUCT_ONLY_PASSWORD = '1111';

// 구글 드라이브 API 범위
const SCOPES = 'https://www.googleapis.com/auth/drive.file';

const generateId = (prefix: string) => `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

const calculateStock = (item: Item): number => {
  return item.transactions.reduce((acc, t) => {
    return t.type === 'purchase' ? acc + t.quantity : acc - t.quantity;
  }, 0);
};

const App: React.FC = () => {
  const [authRole, setAuthRole] = useState<'admin' | 'product_only' | null>(null);
  const [loginPassword, setLoginPassword] = useState('');
  const [activeTab, setActiveTab] = useState<'part' | 'product'>('part');
  const [items, setItems] = useState<Item[]>([]);
  const [showAddItemModal, setShowAddItemModal] = useState(false);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [deletePassword, setDeletePassword] = useState('');

  // 구글 드라이브 관련 상태
  const [isDriveConfigModalOpen, setIsDriveConfigModalOpen] = useState(false);
  const [driveConfig, setDriveConfig] = useState({
    clientId: '',
    folderId: '',
  });
  const [isBackupLoading, setIsBackupLoading] = useState(false);
  const tokenClientRef = useRef<any>(null);

  // 데이터 로드
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY);
    if (savedItems) {
      try {
        setItems(JSON.parse(savedItems));
      } catch (e) {
        console.error("Failed to load inventory data", e);
      }
    }

    const savedConfig = localStorage.getItem(DRIVE_CONFIG_KEY);
    if (savedConfig) {
      setDriveConfig(JSON.parse(savedConfig));
    }
  }, []);

  // 데이터 저장
  useEffect(() => {
    if (items.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
    }
  }, [items]);

  useEffect(() => {
    if (authRole === 'product_only') {
      setActiveTab('product');
    } else if (authRole === 'admin') {
      setActiveTab('part');
    }
  }, [authRole]);

  // 구글 드라이브 백업 로직
  const handleDriveBackup = async () => {
    if (!driveConfig.clientId) {
      alert('백업을 위해 먼저 설정을 통해 Google Client ID를 입력해주세요.');
      setIsDriveConfigModalOpen(true);
      return;
    }

    setIsBackupLoading(true);

    try {
      // 1. Google API 초기화 및 토큰 요청
      const client = (window as any).google.accounts.oauth2.initTokenClient({
        client_id: driveConfig.clientId,
        scope: SCOPES,
        callback: async (response: any) => {
          if (response.error) {
            setIsBackupLoading(false);
            alert('인증에 실패했습니다: ' + response.error);
            return;
          }

          // 2. 파일 찾기 및 업로드 (gapi 로드 필요)
          (window as any).gapi.load('client', async () => {
            await (window as any).gapi.client.init({});
            await (window as any).gapi.client.load('drive', 'v3');

            const accessToken = response.access_token;
            (window as any).gapi.client.setToken({ access_token: accessToken });

            // 기존 백업 파일 찾기
            const searchResponse = await (window as any).gapi.client.drive.files.list({
              q: "name = 'inventory_backup.json' and trashed = false",
              fields: 'files(id)',
              spaces: 'drive',
            });

            const files = searchResponse.result.files;
            const fileData = JSON.stringify(items);
            const boundary = '-------314159265358979323846';
            const delimiter = "\r\n--" + boundary + "\r\n";
            const close_delim = "\r\n--" + boundary + "--";

            const metadata = {
              name: 'inventory_backup.json',
              mimeType: 'application/json',
              parents: driveConfig.folderId ? [driveConfig.folderId] : undefined,
            };

            const multipartRequestBody =
              delimiter +
              'Content-Type: application/json\r\n\r\n' +
              JSON.stringify(metadata) +
              delimiter +
              'Content-Type: application/json\r\n\r\n' +
              fileData +
              close_delim;

            let uploadResponse;
            if (files && files.length > 0) {
              // 업데이트
              uploadResponse = await fetch(
                `https://www.googleapis.com/upload/drive/v3/files/${files[0].id}?uploadType=multipart`,
                {
                  method: 'PATCH',
                  headers: {
                    Authorization: 'Bearer ' + accessToken,
                    'Content-Type': 'multipart/related; boundary=' + boundary,
                  },
                  body: multipartRequestBody,
                }
              );
            } else {
              // 신규 생성
              uploadResponse = await fetch(
                'https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart',
                {
                  method: 'POST',
                  headers: {
                    Authorization: 'Bearer ' + accessToken,
                    'Content-Type': 'multipart/related; boundary=' + boundary,
                  },
                  body: multipartRequestBody,
                }
              );
            }

            if (uploadResponse.ok) {
              alert('구글 드라이브에 성공적으로 백업되었습니다!');
            } else {
              const err = await uploadResponse.json();
              alert('백업 실패: ' + (err.error?.message || '알 수 없는 오류'));
            }
            setIsBackupLoading(false);
          });
        },
      });

      client.requestAccessToken();
    } catch (error) {
      console.error(error);
      alert('백업 과정 중 오류가 발생했습니다.');
      setIsBackupLoading(false);
    }
  };

  const handleSaveDriveConfig = (e: React.FormEvent) => {
    e.preventDefault();
    localStorage.setItem(DRIVE_CONFIG_KEY, JSON.stringify(driveConfig));
    setIsDriveConfigModalOpen(false);
    alert('백업 설정이 저장되었습니다.');
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginPassword === ADMIN_PASSWORD) {
      setAuthRole('admin');
    } else if (loginPassword === PRODUCT_ONLY_PASSWORD) {
      setAuthRole('product_only');
    } else {
      alert('비밀번호가 틀렸습니다.');
    }
    setLoginPassword('');
  };

  const handleLogout = () => {
    setAuthRole(null);
    setSearchTerm('');
  };

  const selectedItem = useMemo(() => 
    items.find(item => item.id === selectedItemId) || null
  , [items, selectedItemId]);

  const handleAddItem = (itemData: Omit<Item, 'id' | 'transactions'>, initialQuantity: number) => {
    const newItem: Item = {
      ...itemData,
      id: generateId('item'),
      transactions: [],
    };
    if (initialQuantity > 0) {
      newItem.transactions.push({
        id: generateId('t'),
        type: 'purchase',
        quantity: initialQuantity,
        date: new Date().toISOString(),
        remarks: '초기 수량 등록',
      });
    }
    setItems(prevItems => [newItem, ...prevItems]);
  };

  const handleUpdateItem = (itemId: string, updatedData: Partial<Item>) => {
    setItems(prevItems =>
      prevItems.map(item => (item.id === itemId ? { ...item, ...updatedData } : item))
    );
  };

  const handleAddTransaction = (itemId: string, transaction: Omit<Transaction, 'id'>) => {
    setItems(prevItems =>
      prevItems.map(item => {
        if (item.id === itemId) {
          return {
            ...item,
            transactions: [...item.transactions, { ...transaction, id: generateId('t') }],
          };
        }
        return item;
      })
    );
  };

  const handleUpdateTransaction = (itemId: string, transactionId: string, updatedData: Partial<Transaction>) => {
    setItems(prevItems =>
      prevItems.map(item => {
        if (item.id === itemId) {
          return {
            ...item,
            transactions: item.transactions.map(t => t.id === transactionId ? { ...t, ...updatedData } : t)
          };
        }
        return item;
      })
    );
  };

  const handleDeleteTransaction = (itemId: string, transactionId: string) => {
    setItems(prevItems =>
      prevItems.map(item => {
        if (item.id === itemId) {
          return {
            ...item,
            transactions: item.transactions.filter(t => t.id !== transactionId)
          };
        }
        return item;
      })
    );
  };

  const handleDeleteItem = () => {
    const currentPass = authRole === 'admin' ? ADMIN_PASSWORD : PRODUCT_ONLY_PASSWORD;
    if (deletePassword !== currentPass) {
      alert('비밀번호가 틀렸습니다.');
      return;
    }

    if (itemToDelete) {
      setItems(prevItems => prevItems.filter(item => item.id !== itemToDelete));
      if (selectedItemId === itemToDelete) {
        setSelectedItemId(null);
      }
      setItemToDelete(null);
      setDeletePassword('');
      alert('품목이 성공적으로 삭제되었습니다.');
    }
  };

  const filteredItems = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return items.filter(item => {
        const matchesTab = item.type === activeTab;
        const matchesSearch = 
            item.name.toLowerCase().includes(term) ||
            item.code.toLowerCase().includes(term) ||
            (item.drawingNumber && item.drawingNumber.toLowerCase().includes(term)) ||
            item.transactions.some(t => t.serialNumber && t.serialNumber.toLowerCase().includes(term));
        return matchesTab && matchesSearch;
    });
  }, [items, searchTerm, activeTab]);

  const existingCodes = useMemo(() => items.map(item => item.code), [items]);

  const allUsedSerials = useMemo(() => {
    return items.flatMap(item => 
      item.transactions.map(t => t.serialNumber).filter((s): s is string => !!s)
    );
  }, [items]);

  const stats = useMemo(() => {
    const partItems = items.filter(i => i.type === 'part');
    const productItems = items.filter(i => i.type === 'product');
    return {
      partCount: partItems.length,
      productCount: productItems.length,
      partStock: partItems.reduce((sum, i) => sum + calculateStock(i), 0),
      productStock: productItems.reduce((sum, i) => sum + calculateStock(i), 0),
    };
  }, [items]);

  const exportToExcel = () => {
    const itemsToExport = items.filter(item => item.type === activeTab);
    if (itemsToExport.length === 0) {
      alert('내보낼 데이터가 없습니다.');
      return;
    }

    let csvContent = "\ufeff"; 
    const headers = activeTab === 'part' 
      ? ['코드', '품명', '도번', '현재재고', '등록일', '비고']
      : ['코드', '제품명', '현재재고', '등록일', '비고'];

    csvContent += headers.join(',') + '\r\n';

    itemsToExport.forEach(item => {
      const stock = calculateStock(item);
      const row = activeTab === 'part'
        ? [item.code, item.name, item.drawingNumber || '', stock, item.registrationDate, item.remarks || '']
        : [item.code, item.name, stock, item.registrationDate, item.remarks || ''];

      const escapedRow = row.map(val => {
        const str = String(val).replace(/"/g, '""');
        return str.includes(',') || str.includes('\n') ? `"${str}"` : str;
      });
      csvContent += escapedRow.join(',') + '\r\n';
    });

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    const dateStr = new Date().toISOString().split('T')[0];
