    e.preventDefault();
    if (!formData.code || !formData.name) {
      alert('품명과 코드는 필수 항목입니다.');
      return;
    }
    const { initialQuantity, ...rest } = formData;
    const quantity = parseInt(initialQuantity, 10) || 0;
    onAddItem({
      ...rest,
      type: itemType,
      modelName: '',
      application: ''
    }, quantity);
    onClose();
  };

