import React, { useState } from 'react';
import type { OrderedPart } from '../types';
import { CloseIcon } from './icons';

interface EditOrderedPartModalProps {
  part: OrderedPart;
  onUpdate: (id: string, updatedData: Partial<OrderedPart>) => void;
  onClose: () => void;
  existingParts: OrderedPart[];
}

const EditOrderedPartModal: React.FC<EditOrderedPartModalProps> = ({ part, onUpdate, onClose, existingParts }) => {
  const [formData, setFormData] = useState({
    code: part.code || '',
    drawingNumber: part.drawingNumber || '',
    name: part.name,
    spec: part.spec || '',
    unitPrice: part.unitPrice.toString(),
    remarks: part.remarks || ''
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    // 코드와 품명(name)만 항상 대문자로 변환
    const processedValue = ['code', 'name'].includes(name) ? value.toUpperCase() : value;
    setFormData(prev => ({ ...prev, [name]: processedValue }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name.trim()) { alert('품명은 필수 입력 사항입니다.'); return; }

    if (formData.code.trim() && formData.code.toUpperCase() !== part.code?.toUpperCase()) {
      const isCodeDup = existingParts.some(p => p.id !== part.id && p.code?.toUpperCase() === formData.code.toUpperCase());
      if (isCodeDup) { alert('이미 등록된 코드입니다.'); return; }
    }

    onUpdate(part.id, {
      code: formData.code.trim(),
      drawingNumber: formData.drawingNumber.trim(),
      name: formData.name.trim(),
      spec: formData.spec.trim(),
      unitPrice: Number(formData.unitPrice) || 0,
      remarks: formData.remarks.trim()
    });
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex justify-center items-center z-50 p-4 font-sans">
