          <button onClick={onClose} className="p-2 text-slate-400 hover:text-slate-800 transition-colors"><CloseIcon className="w-6 h-6" /></button>
        </div>
        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div><label className="block text-[10px] uppercase font-black text-slate-400 mb-1 tracking-widest uppercase">코드</label>
              <input type="text" name="code" value={formData.code} onChange={handleChange} className="w-full px-3 py-2 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 outline-none font-mono font-bold" /></div>
            <div><label className="block text-[10px] uppercase font-black text-slate-400 mb-1 tracking-widest uppercase">도번</label>
