                        <button onClick={handleActionConfirm} className="py-3 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-200 transition-all uppercase text-xs">확인</button>
                    </div>
                </div>
            </div>
