                                </div>
                                <input type="text" value={serialNumber} onChange={(e) => setSerialNumber(e.target.value.toUpperCase())} placeholder="예: SN001~005" className={`w-full px-3 py-2 text-sm border-2 rounded-lg font-bold outline-none focus:ring-2 focus:ring-indigo-500 ${isSerialDuplicate ? 'border-rose-400 bg-rose-50 text-rose-600' : 'border-slate-200'}`} />
