            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-black text-slate-800 uppercase tracking-widest">전체 수불 히스토리</h3>
              <button onClick={exportHistoryToExcel} className="flex items-center gap-2 px-5 py-3 bg-emerald-50 text-emerald-600 border-2 border-emerald-100 rounded-2xl text-sm font-black hover:bg-emerald-600 hover:text-white transition-all uppercase shadow-md">
                <DownloadIcon className="w-5 h-5" /><span>히스토리 내보내기</span></button>
            </div>
            <div className="flex-grow border-2 border-slate-100 rounded-[2rem] overflow-hidden bg-slate-50/50">
                <div className="h-full max-h-[calc(90vh-220px)] overflow-y-auto">
                    {item.transactions.length === 0 ? (<div className="flex flex-col items-center justify-center h-full p-20 opacity-20"><BoxIcon className="w-24 h-24 mb-4" /><p className="text-xl font-black uppercase tracking-widest">기록된 내역이 없습니다</p></div>) : (
                        <div className="overflow-x-auto"><table className="w-full text-left text-base">
                            <thead className="bg-white border-b-2 border-slate-100 text-sm font-black uppercase text-slate-400 sticky top-0 z-10"><tr><th className="px-6 py-5">날짜 / 구분</th><th className="px-6 py-5">수량</th>{item.type === 'part' && <th className="px-6 py-5">기종</th>}{item.type === 'product' && (<><th className="px-6 py-5">일련번호</th><th className="px-6 py-5">대상자</th><th className="px-6 py-5">주소</th></>)}<th className="px-6 py-5">비고</th><th className="px-6 py-5 text-center">작업</th></tr></thead>
                            <tbody className="divide-y-2 divide-white">
                                {[...item.transactions].reverse().map(t => (
                                    <tr key={t.id} className={`hover:bg-white transition-all group ${editingTransactionId === t.id ? 'bg-indigo-50/50' : ''}`}><td className="px-6 py-6"><div className="flex items-center gap-4"><div className={`p-2 rounded-xl ${t.type === 'purchase' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>{t.type === 'purchase' ? <ArrowUpIcon className="w-5 h-5"/> : <ArrowDownIcon className="w-5 h-5"/>}</div><div><p className="font-black text-slate-700 text-lg">{new Date(t.date).toLocaleDateString()}</p><p className="text-xs text-slate-400 font-bold">{new Date(t.date).toLocaleTimeString()}</p></div></div></td>
                                        <td className="px-6 py-6">{editingTransactionId === t.id ? (<input name="quantity" type="number" value={transEditData.quantity} onChange={handleTransEditChange} className="w-24 px-3 py-2 border-2 rounded-xl bg-white font-black text-lg" />) : (<span className={`font-black text-2xl ${t.type === 'purchase' ? 'text-emerald-600' : 'text-rose-600'}`}>{t.type === 'purchase' ? '+' : '-'}{t.quantity.toLocaleString()}</span>)}</td>
                                        {item.type === 'part' && (<td className="px-6 py-6">{editingTransactionId === t.id ? (<input name="modelName" value={transEditData.modelName || ''} onChange={handleTransEditChange} className="w-32 px-3 py-2 border-2 rounded-xl bg-white" />) : (<span className="font-black text-slate-600">{t.modelName || '-'}</span>)}</td>)}
                                        {item.type === 'product' && (<><td className="px-6 py-6">{editingTransactionId === t.id ? (<input name="serialNumber" value={transEditData.serialNumber || ''} onChange={handleTransEditChange} className="w-32 px-3 py-2 border-2 rounded-xl bg-white font-black uppercase" />) : (<span className="font-mono font-black text-indigo-600 text-lg">{t.serialNumber || '-'}</span>)}</td><td className="px-6 py-6">{editingTransactionId === t.id ? (<div className="space-y-2"><input name="customerName" value={transEditData.customerName || ''} onChange={handleTransEditChange} placeholder="이름" className="w-full px-3 py-2 border-2 rounded-xl bg-white" /><input name="phoneNumber" value={transEditData.phoneNumber || ''} onChange={handleTransEditChange} placeholder="번호" className="w-full px-3 py-2 border-2 rounded-xl bg-white" /></div>) : (<><p className="font-black text-slate-800 text-lg">{t.customerName || '-'}</p><p className="text-slate-400 font-bold text-sm">{t.phoneNumber || '-'}</p></>)}</td><td className="px-6 py-6">{editingTransactionId === t.id ? (<input name="address" value={transEditData.address || ''} onChange={handleTransEditChange} placeholder="주소" className="w-full px-3 py-2 border-2 rounded-xl bg-white" />) : (<p className="text-slate-500 font-bold truncate max-w-[200px]" title={t.address}>{t.address || '-'}</p>)}</td></>)}
                                        <td className="px-6 py-6">{editingTransactionId === t.id ? (<input name="remarks" value={transEditData.remarks || ''} onChange={handleTransEditChange} placeholder="비고" className="w-full px-3 py-2 border-2 rounded-xl bg-white" />) : (<p className="text-sm text-slate-400 font-black truncate max-w-[250px]">{t.remarks || '-'}</p>)}</td>
                                        <td className="px-6 py-6 text-center"><div className="flex items-center justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                            {editingTransactionId === t.id ? (<><button onClick={() => handleSaveTransEdit(t.id)} className="p-3 text-emerald-600 hover:bg-emerald-50 rounded-xl transition-all"><CheckIcon className="w-6 h-6" /></button><button onClick={() => setEditingTransactionId(null)} className="p-3 text-slate-400 hover:bg-slate-50 rounded-xl transition-all"><CloseIcon className="w-6 h-6" /></button></>) : (<><button onClick={() => handleEditTransaction(t)} className="p-3 text-indigo-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all"><EditIcon className="w-6 h-6" /></button><button onClick={() => handleDeleteTrans(t.id)} className="p-3 text-rose-400 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all"><TrashIcon className="w-6 h-6" /></button></>)}
                                          </div></td></tr>
                                ))}</tbody></table></div>
                    )}
                </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ItemDetailModal;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import type { Item, Transaction } from './types';
import AddItemModal from './components/AddItemModal';
import ItemDetailModal from './components/ItemDetailModal';
import { PlusIcon, BoxIcon, SearchIcon, TrashIcon, DownloadIcon, CloudIcon, ServerIcon } from './components/icons';

const STORAGE_KEY = 'inventory_system_data_v2';
const ADMIN_PASSWORD = '0000';
const PRODUCT_ONLY_PASSWORD = '1111';

const generateId = (prefix: string) => `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

const calculateStock = (item: Item): number => {
  return item.transactions.reduce((acc, t) => {
    return t.type === 'purchase' ? acc + t.quantity : acc - t.quantity;
  }, 0);
};

const App: React.FC = () => {
  const [authRole, setAuthRole] = useState<'admin' | 'product_only' | null>(null);
  const [loginPassword, setLoginPassword] = useState('');
  const [activeTab, setActiveTab] = useState<'part' | 'product'>('part');

  const [items, setItems] = useState<Item[]>([]);
  const [showAddItemModal, setShowAddItemModal] = useState(false);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<{id: string, type: 'inventory'} | null>(null);
  const [deletePassword, setDeletePassword] = useState('');

  const [syncStatus, setSyncStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const fetchFromServer = async () => {
    setSyncStatus('loading');
    try {
      const response = await fetch('/api/inventory');
      if (response.ok) {
        const data = await response.json();
        if (data && Array.isArray(data.items)) {
          setItems(data.items);
          setSyncStatus('success');
          return;
        }
      }
      throw new Error('Server Fetch Failed');
    } catch (err) {
      console.warn('서버에서 데이터를 가져오지 못했습니다. 로컬 데이터를 사용합니다.');
      const savedItems = localStorage.getItem(STORAGE_KEY);
      if (savedItems) setItems(JSON.parse(savedItems));
      setSyncStatus('error');
    }
  };

  const saveToServer = async (data: Item[]) => {
    setSyncStatus('loading');
    try {
      const response = await fetch('/api/inventory', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: data, updatedAt: new Date().toISOString() }),
      });
      if (response.ok) setSyncStatus('success');
      else throw new Error('Server Save Failed');
    } catch (err) {
      setSyncStatus('error');
      console.error('서버 동기화 실패:', err);
    }
  };

  useEffect(() => {
    fetchFromServer();
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
    if (items.length > 0) {
      const timer = setTimeout(() => saveToServer(items), 1000);
      return () => clearTimeout(timer);
    }
  }, [items]);

  const stats = useMemo(() => {
    return {
      partCount: items.filter(i => i.type === 'part').length,
      productCount: items.filter(i => i.type === 'product').length,
    };
  }, [items]);

  const allUsedSerials = useMemo(() => {
    const serials: string[] = [];
    items.forEach(item => {
      item.transactions.forEach(t => {
        if (t.serialNumber) serials.push(t.serialNumber.toUpperCase());
      });
    });
    return Array.from(new Set(serials));
  }, [items]);

  const handleLocalExport = async () => {
    const dataObj = { items, version: '2.0', exportDate: new Date().toISOString() };
    const jsonStr = JSON.stringify(dataObj, null, 2);

    if ('showSaveFilePicker' in window) {
      try {
        const handle = await (window as any).showSaveFilePicker({
          suggestedName: `재고관리_백업_${new Date().toISOString().split('T')[0]}.json`,
          types: [{
            description: 'JSON File',
            accept: { 'application/json': ['.json'] },
          }],
        });
        const writable = await handle.createWritable();
        await writable.write(jsonStr);
        await writable.close();
        alert('파일이 지정된 위치에 저장되었습니다.');
        return;
      } catch (err: any) {
        if (err.name === 'AbortError') return;
        console.error('File API Error:', err);
      }
    }

    const blob = new Blob([jsonStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `재고관리_백업_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLocalImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.items && Array.isArray(json.items)) {
          if (confirm('가져온 데이터로 현재 시스템을 복구하시겠습니까?\n(현재의 모든 데이터가 덮어씌워집니다.)')) {
            setItems(json.items);
            alert('데이터 복구가 완료되었습니다.');
          }
        } else {
          alert('올바른 백업 파일 형식이 아닙니다.');
        }
      } catch (err) {
        alert('파일을 읽는 중 오류가 발생했습니다.');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginPassword === ADMIN_PASSWORD) setAuthRole('admin');
    else if (loginPassword === PRODUCT_ONLY_PASSWORD) setAuthRole('product_only');
    else alert('비밀번호가 틀렸습니다.');
    setLoginPassword('');
  };

  const handleLogout = () => {
    setAuthRole(null);
    setSearchTerm('');
  };

  const handleAddItem = (itemData: Omit<Item, 'id' | 'transactions'>, initialQuantity: number) => {
    const newItem: Item = { ...itemData, id: generateId('item'), transactions: [] };
    if (initialQuantity > 0) {
      newItem.transactions.push({
        id: generateId('t'), type: 'purchase', quantity: initialQuantity,
        date: new Date().toISOString(), remarks: '초기 수량 등록',
      });
    }
    setItems(prev => [newItem, ...prev]);
  };

  const handleDeleteItemConfirm = () => {
    const currentPass = authRole === 'admin' ? ADMIN_PASSWORD : PRODUCT_ONLY_PASSWORD;
    if (deletePassword !== currentPass) {
      alert('비밀번호가 틀렸습니다.');
      return;
    }
    if (itemToDelete) {
      setItems(prev => prev.filter(i => i.id !== itemToDelete.id));
      setItemToDelete(null);
      setDeletePassword('');
    }
  };

  const handleUpdateItem = (itemId: string, updatedData: Partial<Item>) => {
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, ...updatedData } : item));
  };

  const handleAddTransaction = (itemId: string, transaction: Omit<Transaction, 'id'>) => {
    const newTransaction: Transaction = { ...transaction, id: generateId('t') };
    setItems(prev => prev.map(item => {
      if (item.id === itemId) {
        return { ...item, transactions: [...item.transactions, newTransaction] };
      }
      return item;
    }));
  };

  const handleUpdateTransaction = (itemId: string, transactionId: string, updatedData: Partial<Transaction>) => {
    setItems(prev => prev.map(item => {
      if (item.id === itemId) {
        return { ...item, transactions: item.transactions.map(t => t.id === transactionId ? { ...t, ...updatedData } : t) };
      }
      return item;
    }));
  };

  const handleDeleteTransaction = (itemId: string, transactionId: string) => {
    setItems(prev => prev.map(item => {
      if (item.id === itemId) {
        return { ...item, transactions: item.transactions.filter(t => t.id !== transactionId) };
      }
      return item;
    }));
  };

  const selectedItem = useMemo(() => items.find(i => i.id === selectedItemId), [items, selectedItemId]);

  const filteredInventory = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    return items.filter(item => {
        const matchesTab = (activeTab === 'part' && item.type === 'part') || (activeTab === 'product' && item.type === 'product');
        if (!matchesTab) return false;
        const basicMatch = item.name.toLowerCase().includes(term) || item.code.toLowerCase().includes(term);
        if (basicMatch) return true;
        if (activeTab === 'product') return item.transactions.some(t => t.serialNumber?.toLowerCase().includes(term));
        return false;
    });
  }, [items, searchTerm, activeTab]);

  const exportToExcel = () => {
    let csvContent = "\ufeff";
    const headers = activeTab === 'part' ? ['코드', '품명', '도번', '현재재고'] : ['코드', '제품명', '현재재고'];
    csvContent += headers.join(',') + '\r\n';
    filteredInventory.forEach(item => {
      const row = activeTab === 'part' 
        ? [item.code, item.name, item.drawingNumber, calculateStock(item)]
        : [item.code, item.name, calculateStock(item)];
      csvContent += row.map(v => `"${String(v).replace(/"/g, '""')}"`).join(',') + '\r\n';
    });
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `${activeTab === 'part' ? '부품' : '제품'}_재고_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  if (!authRole) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md p-10 animate-fade-in-up border border-slate-100">
          <div className="flex flex-col items-center mb-10">
            <div className="bg-indigo-600 p-4 rounded-2xl shadow-lg mb-6">
              <BoxIcon className="w-12 h-12 text-white" />
            </div>
            <h1 className="text-3xl font-black text-slate-800 tracking-tight uppercase">재고 관리 시스템</h1>
          </div>
          <form onSubmit={handleLogin} className="space-y-6">
            <input 
              type="password" autoFocus value={loginPassword}
              onChange={(e) => setLoginPassword(e.target.value)}
              placeholder="PASSWORD"
              className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-600 outline-none text-center text-4xl font-black tracking-[0.5em] transition-all"
            />
            <button type="submit" className="w-full py-5 bg-indigo-600 text-white font-black rounded-xl shadow-xl hover:bg-indigo-700 transition-all text-xl">로그인</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 font-sans">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-20 shadow-sm">
        <div className="container mx-auto px-4 sm:px-6">
            <div className="flex justify-between items-center py-5">
                <div className="flex items-center space-x-4">
                    <BoxIcon className="h-9 w-9 text-indigo-600" />
                    <h1 className="text-2xl font-bold text-slate-900 tracking-tight uppercase">재고 관리 시스템</h1>
                </div>
                <div className="flex items-center space-x-3">
                  <div className="flex items-center space-x-2 px-3 py-1.5 bg-slate-50 rounded-full border border-slate-100 mr-2">
                    <div className={`w-2.5 h-2.5 rounded-full ${syncStatus === 'success' ? 'bg-emerald-500' : syncStatus === 'loading' ? 'bg-amber-500 animate-pulse' : 'bg-rose-500'}`}></div>
                    <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">
                        {syncStatus === 'success' ? 'Synced' : syncStatus === 'loading' ? 'Syncing' : 'Error'}
                    </span>
                  </div>

                  {/* 데이터 관리 버튼들 (헤더로 이동 및 소형화) */}
                  <button onClick={handleLocalExport} className="flex items-center gap-1.5 px-3 py-1.5 bg-slate-800 text-white font-black rounded-lg hover:bg-slate-900 transition-all text-[10px] uppercase tracking-wider">
                      <DownloadIcon className="w-3.5 h-3.5" />
                      <span>내보내기</span>
                  </button>
                  <label className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-slate-200 text-slate-600 font-black rounded-lg hover:bg-slate-50 transition-all text-[10px] cursor-pointer uppercase tracking-wider">
                      <CloudIcon className="w-3.5 h-3.5" />
                      <span>가져오기</span>
                      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleLocalImport} />
                  </label>

                  <div className="w-px h-4 bg-slate-200 mx-1"></div>

                  <button onClick={handleLogout} className="px-4 py-1.5 bg-slate-100 text-slate-500 rounded-lg hover:bg-slate-200 transition-colors font-black text-[10px] uppercase">Logout</button>
                </div>
            </div>
            <div className="flex space-x-12 -mb-px">
                {authRole === 'admin' && (
                  <button onClick={() => setActiveTab('part')} className={`pb-4 px-2 text-lg font-black uppercase tracking-widest transition-all border-b-4 ${activeTab === 'part' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                    부품 재고관리 ({stats.partCount})
                  </button>
                )}
                <button onClick={() => setActiveTab('product')} className={`pb-4 px-2 text-lg font-black uppercase tracking-widest transition-all border-b-4 ${activeTab === 'product' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                  제품 재고관리 ({stats.productCount})
                </button>
            </div>
        </div>
      </header>

      <main className="container mx-auto p-4 sm:p-8">
        <div className="flex flex-col xl:flex-row xl:justify-between xl:items-center gap-6 mb-10">
          <div className="relative flex-grow max-w-3xl">
              <span className="absolute inset-y-0 left-0 flex items-center pl-5"><SearchIcon className="text-slate-400 w-6 h-6" /></span>
              <input
                  type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value.toUpperCase())}
                  placeholder="품명, 코드, 일련번호 검색..."
                  className="w-full pl-14 pr-6 py-4 border-2 border-slate-100 rounded-2xl focus:outline-none focus:border-indigo-400 bg-white shadow-sm font-bold text-lg transition-all"
              />
          </div>
          <div className="flex flex-wrap gap-3">
            <button onClick={exportToExcel} className="flex items-center gap-2 px-8 py-4 bg-emerald-600 text-white font-black rounded-xl shadow-lg hover:bg-emerald-700 transition-all text-base uppercase tracking-widest">
                <ServerIcon className="w-5 h-5" />
                <span>엑셀 파일 저장</span>
            </button>
            <button onClick={() => setShowAddItemModal(true)} className="flex items-center gap-2 px-10 py-4 bg-indigo-600 text-white font-black rounded-xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all text-base uppercase tracking-widest">
                <PlusIcon className="w-6 h-6" />
                <span>신규 등록</span>
            </button>
          </div>
        </div>

        <div className="bg-white shadow-2xl border border-slate-100 rounded-[2.5rem] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="text-sm text-slate-400 uppercase bg-slate-50/50 border-b border-slate-100 font-black tracking-[0.2em]">
                <tr>
                  <th className="px-10 py-7">품목 코드</th>
                  <th className="px-10 py-7">품명 / 제품명</th>
                  {activeTab === 'part' && <th className="px-10 py-7">도번</th>}
                  <th className="px-10 py-7 text-right">현재 재고수량</th>
                  <th className="px-10 py-7 text-center">관리</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {filteredInventory.length === 0 ? (
                  <tr><td colSpan={5} className="px-10 py-24 text-center text-slate-300 font-black uppercase tracking-widest italic text-2xl">기록된 데이터가 없습니다</td></tr>
                ) : (
                  filteredInventory.map(item => {
                    const stock = calculateStock(item);
                    return (
                      <tr key={item.id} className="hover:bg-indigo-50/30 transition-colors group">
                        <td className="px-10 py-7 font-mono text-indigo-600 font-black text-xl">{item.code}</td>
                        <td className="px-10 py-7 font-black text-slate-800 text-xl">{item.name}</td>
                        {activeTab === 'part' && <td className="px-10 py-7 text-slate-400 font-mono text-sm uppercase font-bold">{item.drawingNumber || '-'}</td>}
                        <td className="px-10 py-7 text-right">
                            <span className={`text-4xl font-black ${stock > 0 ? 'text-slate-900' : 'text-rose-500 animate-pulse'}`}>
                                {stock.toLocaleString()} <span className="text-xs uppercase text-slate-400 ml-1">EA</span>
                            </span>
                        </td>
                        <td className="px-10 py-7">
                          <div className="flex justify-center gap-4">
                            <button onClick={() => setSelectedItemId(item.id)} className="px-6 py-3 bg-indigo-50 text-indigo-600 rounded-xl font-black text-sm uppercase tracking-wider hover:bg-indigo-600 hover:text-white transition-all shadow-sm">상세</button>
                            <button onClick={() => setItemToDelete({id: item.id, type: 'inventory'})} className="p-3 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-2xl transition-all"><TrashIcon className="w-7 h-7" /></button>
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>
      </main>

      {itemToDelete && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[60] flex items-center justify-center p-4">
            <div className="bg-white rounded-[3rem] p-12 max-w-lg w-full shadow-2xl border border-slate-100 animate-fade-in-up">
                <div className="flex flex-col items-center mb-8">
                    <div className="p-6 bg-rose-50 rounded-[2rem] mb-6"><TrashIcon className="w-14 h-14 text-rose-500" /></div>
                    <h4 className="text-3xl font-black text-slate-800 uppercase tracking-tight">삭제 비밀번호</h4>
                    <p className="text-sm text-slate-400 font-bold mt-2 uppercase tracking-widest">정말로 삭제하시겠습니까?</p>
                </div>
                <input type="password" autoFocus value={deletePassword} onChange={(e) => setDeletePassword(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleDeleteItemConfirm()} placeholder="PASSWORD" className="w-full px-6 py-6 border-2 border-slate-100 rounded-3xl focus:border-rose-500 outline-none mb-8 text-center text-4xl font-black tracking-widest" />
                <div className="grid grid-cols-2 gap-6">
                    <button onClick={() => setItemToDelete(null)} className="py-5 bg-slate-100 text-slate-600 rounded-2xl font-black uppercase text-sm tracking-widest">취소</button>
                    <button onClick={handleDeleteItemConfirm} className="py-5 bg-rose-600 text-white rounded-2xl font-black uppercase text-sm tracking-widest shadow-lg shadow-rose-100">삭제 확정</button>
                </div>
            </div>
        </div>
      )}

      {showAddItemModal && (
        <AddItemModal onAddItem={handleAddItem} onClose={() => setShowAddItemModal(false)} existingCodes={items.map(i => i.code)} defaultType={activeTab === 'product' ? 'product' : 'part'} />
      )}
      {selectedItemId && selectedItem && (
        <ItemDetailModal 
          item={selectedItem} 
          authRole={authRole as any} 
          allUsedSerials={allUsedSerials} 
          existingCodes={items.map(i => i.code)}
          onAddTransaction={handleAddTransaction} 
          onUpdateTransaction={handleUpdateTransaction} 
          onDeleteTransaction={handleDeleteTransaction} 
          onUpdateItem={handleUpdateItem} 
          onClose={() => setSelectedItemId(null)} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import type { Item, Transaction } from './types';
import AddItemModal from './components/AddItemModal';
import ItemDetailModal from './components/ItemDetailModal';
import { PlusIcon, BoxIcon, SearchIcon, TrashIcon, DownloadIcon, CloudIcon, ServerIcon } from './components/icons';

const STORAGE_KEY = 'inventory_system_data_v2';
const ADMIN_PASSWORD = '0000';
const PRODUCT_ONLY_PASSWORD = '1111';

const generateId = (prefix: string) => `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

const calculateStock = (item: Item): number => {
  return item.transactions.reduce((acc, t) => {
    return t.type === 'purchase' ? acc + t.quantity : acc - t.quantity;
  }, 0);
};

const App: React.FC = () => {
  const [authRole, setAuthRole] = useState<'admin' | 'product_only' | null>(null);
  const [loginPassword, setLoginPassword] = useState('');
  const [activeTab, setActiveTab] = useState<'part' | 'product'>('part');

  const [items, setItems] = useState<Item[]>([]);
  const [showAddItemModal, setShowAddItemModal] = useState(false);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<{id: string, type: 'inventory'} | null>(null);
  const [deletePassword, setDeletePassword] = useState('');

  const [syncStatus, setSyncStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const fetchFromServer = async () => {
    setSyncStatus('loading');
    try {
      // NOTE: /api/inventory 엔드포인트가 서버에 구현되어 있어야 Upstash 등과 연동됩니다.
      const response = await fetch('/api/inventory');
      if (response.ok) {
        const data = await response.json();
        if (data && Array.isArray(data.items)) {
          setItems(data.items);
          setSyncStatus('success');
          return;
        }
      }
      throw new Error('Server Fetch Failed');
    } catch (err) {
      console.warn('서버 연결 실패. 로컬 데이터를 사용합니다.');
      const savedItems = localStorage.getItem(STORAGE_KEY);
      if (savedItems) setItems(JSON.parse(savedItems));
      setSyncStatus('error');
    }
  };

  const saveToServer = async (data: Item[]) => {
    setSyncStatus('loading');
    try {
      const response = await fetch('/api/inventory', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: data, updatedAt: new Date().toISOString() }),
      });
      if (response.ok) setSyncStatus('success');
      else throw new Error('Server Save Failed');
    } catch (err) {
      setSyncStatus('error');
    }
  };

  useEffect(() => {
    fetchFromServer();
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
    if (items.length > 0) {
      const timer = setTimeout(() => saveToServer(items), 1000);
      return () => clearTimeout(timer);
    }
  }, [items]);

  const stats = useMemo(() => {
    return {
      partCount: items.filter(i => i.type === 'part').length,
      productCount: items.filter(i => i.type === 'product').length,
    };
  }, [items]);

  const allUsedSerials = useMemo(() => {
    const serials: string[] = [];
    items.forEach(item => {
      item.transactions.forEach(t => {
        if (t.serialNumber) serials.push(t.serialNumber.toUpperCase());
      });
    });
    return Array.from(new Set(serials));
  }, [items]);

  const handleLocalExport = async () => {
    const dataObj = { items, version: '2.0', exportDate: new Date().toISOString() };
    const jsonStr = JSON.stringify(dataObj, null, 2);

    if ('showSaveFilePicker' in window) {
      try {
        const handle = await (window as any).showSaveFilePicker({
          suggestedName: `재고관리_백업_${new Date().toISOString().split('T')[0]}.json`,
          types: [{
            description: 'JSON File',
            accept: { 'application/json': ['.json'] },
          }],
        });
        const writable = await handle.createWritable();
        await writable.write(jsonStr);
        await writable.close();
        alert('파일이 지정된 위치에 저장되었습니다.');
        return;
      } catch (err: any) {
        if (err.name === 'AbortError') return;
        console.error('File API Error:', err);
      }
    }

    const blob = new Blob([jsonStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `재고관리_백업_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLocalImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.items && Array.isArray(json.items)) {
          if (confirm('데이터를 복구하시겠습니까? 현재 데이터가 덮어씌워집니다.')) {
            setItems(json.items);
            alert('복구가 완료되었습니다.');
          }
        } else {
          alert('올바른 파일 형식이 아닙니다.');
        }
      } catch (err) {
        alert('파일을 읽는 중 오류가 발생했습니다.');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginPassword === ADMIN_PASSWORD) setAuthRole('admin');
    else if (loginPassword === PRODUCT_ONLY_PASSWORD) setAuthRole('product_only');
    else alert('비밀번호가 틀렸습니다.');
    setLoginPassword('');
  };

  const handleLogout = () => {
    setAuthRole(null);
    setSearchTerm('');
  };

  const handleAddItem = (itemData: Omit<Item, 'id' | 'transactions'>, initialQuantity: number) => {
    const newItem: Item = { ...itemData, id: generateId('item'), transactions: [] };
    if (initialQuantity > 0) {
      newItem.transactions.push({
        id: generateId('t'), type: 'purchase', quantity: initialQuantity,
        date: new Date().toISOString(), remarks: '초기 수량 등록',
      });
    }
    setItems(prev => [newItem, ...prev]);
  };

  const handleDeleteItemConfirm = () => {
    const currentPass = authRole === 'admin' ? ADMIN_PASSWORD : PRODUCT_ONLY_PASSWORD;
    if (deletePassword !== currentPass) {
      alert('비밀번호가 틀렸습니다.');
      return;
    }
    if (itemToDelete) {
      setItems(prev => prev.filter(i => i.id !== itemToDelete.id));
      setItemToDelete(null);
      setDeletePassword('');
    }
  };

  const handleUpdateItem = (itemId: string, updatedData: Partial<Item>) => {
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, ...updatedData } : item));
  };

  const handleAddTransaction = (itemId: string, transaction: Omit<Transaction, 'id'>) => {
    const newTransaction: Transaction = { ...transaction, id: generateId('t') };
    setItems(prev => prev.map(item => {
      if (item.id === itemId) {
        return { ...item, transactions: [...item.transactions, newTransaction] };
      }
      return item;
    }));
  };

  const handleUpdateTransaction = (itemId: string, transactionId: string, updatedData: Partial<Transaction>) => {
    setItems(prev => prev.map(item => {
      if (item.id === itemId) {
        return { ...item, transactions: item.transactions.map(t => t.id === transactionId ? { ...t, ...updatedData } : t) };
      }
      return item;
    }));
  };

  const handleDeleteTransaction = (itemId: string, transactionId: string) => {
    setItems(prev => prev.map(item => {
      if (item.id === itemId) {
        return { ...item, transactions: item.transactions.filter(t => t.id !== transactionId) };
      }
      return item;
    }));
  };

  const selectedItem = useMemo(() => items.find(i => i.id === selectedItemId), [items, selectedItemId]);

  const filteredInventory = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    return items.filter(item => {
        const matchesTab = (activeTab === 'part' && item.type === 'part') || (activeTab === 'product' && item.type === 'product');
        if (!matchesTab) return false;
        const basicMatch = item.name.toLowerCase().includes(term) || item.code.toLowerCase().includes(term);
        if (basicMatch) return true;
        if (activeTab === 'product') return item.transactions.some(t => t.serialNumber?.toLowerCase().includes(term));
        return false;
    });
  }, [items, searchTerm, activeTab]);

  const exportToExcel = () => {
    let csvContent = "\ufeff";
    const headers = activeTab === 'part' ? ['코드', '품명', '도번', '현재재고'] : ['코드', '제품명', '현재재고'];
    csvContent += headers.join(',') + '\r\n';
    filteredInventory.forEach(item => {
      const row = activeTab === 'part' 
        ? [item.code, item.name, item.drawingNumber, calculateStock(item)]
        : [item.code, item.name, calculateStock(item)];
      csvContent += row.map(v => `"${String(v).replace(/"/g, '""')}"`).join(',') + '\r\n';
    });
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `${activeTab === 'part' ? '부품' : '제품'}_재고_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  if (!authRole) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl w-full max-md p-10 animate-fade-in-up border border-slate-100">
          <div className="flex flex-col items-center mb-10">
            <div className="bg-indigo-600 p-4 rounded-2xl shadow-lg mb-6">
              <BoxIcon className="w-12 h-12 text-white" />
            </div>
            <h1 className="text-3xl font-black text-slate-800 tracking-tight uppercase">재고 관리 시스템</h1>
          </div>
          <form onSubmit={handleLogin} className="space-y-6">
            <input 
              type="password" autoFocus value={loginPassword}
              onChange={(e) => setLoginPassword(e.target.value)}
              placeholder="PASSWORD"
              className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-600 outline-none text-center text-4xl font-black tracking-[0.5em] transition-all"
            />
            <button type="submit" className="w-full py-5 bg-indigo-600 text-white font-black rounded-xl shadow-xl hover:bg-indigo-700 transition-all text-xl">로그인</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 font-sans">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-20 shadow-sm">
        <div className="container mx-auto px-4 sm:px-6">
            <div className="flex justify-between items-center py-4">
                <div className="flex items-center space-x-4">
                    <BoxIcon className="h-8 w-8 text-indigo-600" />
                    <h1 className="text-2xl font-bold text-slate-900 tracking-tight uppercase">재고 관리 시스템</h1>
                </div>

                {/* 우측 영역: 2단 구성 (상단: 상태/로그아웃, 하단: 내보내기/가져오기) */}
                <div className="flex flex-col items-end space-y-2">
                  <div className="flex items-center space-x-3">
                    <div className={`flex items-center space-x-2 px-2.5 py-1 rounded-full border transition-all ${syncStatus === 'success' ? 'bg-emerald-50 border-emerald-100' : 'bg-slate-50 border-slate-100'}`}>
                      <div className={`w-2 h-2 rounded-full ${syncStatus === 'success' ? 'bg-emerald-500' : syncStatus === 'loading' ? 'bg-amber-500 animate-pulse' : 'bg-slate-300'}`}></div>
                      <span className={`text-[10px] font-black uppercase tracking-widest ${syncStatus === 'success' ? 'text-emerald-600' : 'text-slate-400'}`}>
                          {syncStatus === 'success' ? 'Synced' : syncStatus === 'loading' ? 'Syncing' : 'Local Mode'}
                      </span>
                    </div>
                    <button onClick={handleLogout} className="px-3 py-1 bg-slate-100 text-slate-500 rounded-md hover:bg-slate-200 transition-colors font-black text-[10px] uppercase">Logout</button>
                  </div>

                  {/* 로그아웃 밑에 위치하는 소형 버튼들 */}
                  <div className="flex items-center space-x-2">
                    <button onClick={handleLocalExport} className="flex items-center gap-1.5 px-3 py-1 bg-slate-100 text-slate-500 border border-slate-200 rounded-md hover:bg-slate-200 transition-all text-[10px] font-black uppercase tracking-wider">
                        <DownloadIcon className="w-3 h-3" />
                        <span>내보내기</span>
                    </button>
                    <label className="flex items-center gap-1.5 px-3 py-1 bg-slate-100 text-slate-500 border border-slate-200 rounded-md hover:bg-slate-200 transition-all text-[10px] font-black cursor-pointer uppercase tracking-wider">
                        <CloudIcon className="w-3 h-3" />
                        <span>가져오기</span>
                        <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleLocalImport} />
                    </label>
                  </div>
                </div>
            </div>

            <div className="flex space-x-12 -mb-px">
                {authRole === 'admin' && (
                  <button onClick={() => setActiveTab('part')} className={`pb-4 px-2 text-lg font-black uppercase tracking-widest transition-all border-b-4 ${activeTab === 'part' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                    부품 재고관리 ({stats.partCount})
                  </button>
                )}
                <button onClick={() => setActiveTab('product')} className={`pb-4 px-2 text-lg font-black uppercase tracking-widest transition-all border-b-4 ${activeTab === 'product' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                  제품 재고관리 ({stats.productCount})
                </button>
            </div>
        </div>
      </header>

      <main className="container mx-auto p-4 sm:p-8">
        <div className="flex flex-col xl:flex-row xl:justify-between xl:items-center gap-6 mb-10">
          <div className="relative flex-grow max-w-3xl">
              <span className="absolute inset-y-0 left-0 flex items-center pl-5"><SearchIcon className="text-slate-400 w-6 h-6" /></span>
              <input
                  type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value.toUpperCase())}
                  placeholder="품명, 코드, 일련번호 검색..."
                  className="w-full pl-14 pr-6 py-4 border-2 border-slate-100 rounded-2xl focus:outline-none focus:border-indigo-400 bg-white shadow-sm font-bold text-lg transition-all"
              />
          </div>
          <div className="flex flex-wrap gap-3">
            <button onClick={exportToExcel} className="flex items-center gap-2 px-8 py-4 bg-emerald-600 text-white font-black rounded-xl shadow-lg hover:bg-emerald-700 transition-all text-base uppercase tracking-widest">
                <ServerIcon className="w-5 h-5" />
                <span>엑셀 파일 저장</span>
            </button>
            <button onClick={() => setShowAddItemModal(true)} className="flex items-center gap-2 px-10 py-4 bg-indigo-600 text-white font-black rounded-xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all text-base uppercase tracking-widest">
                <PlusIcon className="w-6 h-6" />
                <span>신규 등록</span>
            </button>
          </div>
        </div>

        <div className="bg-white shadow-2xl border border-slate-100 rounded-[2.5rem] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="text-sm text-slate-400 uppercase bg-slate-50/50 border-b border-slate-100 font-black tracking-[0.2em]">
                <tr>
                  <th className="px-10 py-7">품목 코드</th>
                  <th className="px-10 py-7">품명 / 제품명</th>
                  {activeTab === 'part' && <th className="px-10 py-7">도번</th>}
                  <th className="px-10 py-7 text-right">현재 재고수량</th>
                  <th className="px-10 py-7 text-center">관리</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {filteredInventory.length === 0 ? (
                  <tr><td colSpan={5} className="px-10 py-24 text-center text-slate-300 font-black uppercase tracking-widest italic text-2xl">기록된 데이터가 없습니다</td></tr>
                ) : (
                  filteredInventory.map(item => {
                    const stock = calculateStock(item);
                    return (
                      <tr key={item.id} className="hover:bg-indigo-50/30 transition-colors group">
                        <td className="px-10 py-7 font-mono text-indigo-600 font-black text-xl">{item.code}</td>
                        <td className="px-10 py-7 font-black text-slate-800 text-xl">{item.name}</td>
                        {activeTab === 'part' && <td className="px-10 py-7 text-slate-400 font-mono text-sm uppercase font-bold">{item.drawingNumber || '-'}</td>}
                        <td className="px-10 py-7 text-right">
                            <span className={`text-4xl font-black ${stock > 0 ? 'text-slate-900' : 'text-rose-500 animate-pulse'}`}>
                                {stock.toLocaleString()} <span className="text-xs uppercase text-slate-400 ml-1">EA</span>
                            </span>
                        </td>
                        <td className="px-10 py-7">
                          <div className="flex justify-center gap-4">
                            <button onClick={() => setSelectedItemId(item.id)} className="px-6 py-3 bg-indigo-50 text-indigo-600 rounded-xl font-black text-sm uppercase tracking-wider hover:bg-indigo-600 hover:text-white transition-all shadow-sm">상세</button>
                            <button onClick={() => setItemToDelete({id: item.id, type: 'inventory'})} className="p-3 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-2xl transition-all"><TrashIcon className="w-7 h-7" /></button>
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>
      </main>

      {itemToDelete && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[60] flex items-center justify-center p-4">
            <div className="bg-white rounded-[3rem] p-12 max-w-lg w-full shadow-2xl border border-slate-100 animate-fade-in-up">
                <div className="flex flex-col items-center mb-8">
                    <div className="p-6 bg-rose-50 rounded-[2rem] mb-6"><TrashIcon className="w-14 h-14 text-rose-500" /></div>
                    <h4 className="text-3xl font-black text-slate-800 uppercase tracking-tight">삭제 비밀번호</h4>
                    <p className="text-sm text-slate-400 font-bold mt-2 uppercase tracking-widest">정말로 삭제하시겠습니까?</p>
                </div>
                <input type="password" autoFocus value={deletePassword} onChange={(e) => setDeletePassword(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleDeleteItemConfirm()} placeholder="PASSWORD" className="w-full px-6 py-6 border-2 border-slate-100 rounded-3xl focus:border-rose-500 outline-none mb-8 text-center text-4xl font-black tracking-widest" />
                <div className="grid grid-cols-2 gap-6">
                    <button onClick={() => setItemToDelete(null)} className="py-5 bg-slate-100 text-slate-600 rounded-2xl font-black uppercase text-sm tracking-widest">취소</button>
                    <button onClick={handleDeleteItemConfirm} className="py-5 bg-rose-600 text-white rounded-2xl font-black uppercase text-sm tracking-widest shadow-lg shadow-rose-100">삭제 확정</button>
                </div>
            </div>
        </div>
      )}

      {showAddItemModal && (
        <AddItemModal onAddItem={handleAddItem} onClose={() => setShowAddItemModal(false)} existingCodes={items.map(i => i.code)} defaultType={activeTab === 'product' ? 'product' : 'part'} />
      )}
      {selectedItemId && selectedItem && (
        <ItemDetailModal 
          item={selectedItem} 
          authRole={authRole as any} 
          allUsedSerials={allUsedSerials} 
          existingCodes={items.map(i => i.code)}
          onAddTransaction={handleAddTransaction} 
          onUpdateTransaction={handleUpdateTransaction} 
          onDeleteTransaction={handleDeleteTransaction} 
          onUpdateItem={handleUpdateItem} 
          onClose={() => setSelectedItemId(null)} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import type { Item, Transaction } from './types';
import AddItemModal from './components/AddItemModal';
import ItemDetailModal from './components/ItemDetailModal';
import { PlusIcon, BoxIcon, SearchIcon, TrashIcon, DownloadIcon, CloudIcon, ServerIcon } from './components/icons';

const STORAGE_KEY = 'inventory_system_data_v2';
const ADMIN_PASSWORD = '0000';
const PRODUCT_ONLY_PASSWORD = '1111';

const generateId = (prefix: string) => `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

const calculateStock = (item: Item): number => {
  return item.transactions.reduce((acc, t) => {
    return t.type === 'purchase' ? acc + t.quantity : acc - t.quantity;
  }, 0);
};

const App: React.FC = () => {
  const [authRole, setAuthRole] = useState<'admin' | 'product_only' | null>(null);
  const [loginPassword, setLoginPassword] = useState('');
  const [activeTab, setActiveTab] = useState<'part' | 'product'>('part');

  const [items, setItems] = useState<Item[]>([]);
  const [showAddItemModal, setShowAddItemModal] = useState(false);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<{id: string, type: 'inventory'} | null>(null);
  const [deletePassword, setDeletePassword] = useState('');

  const [syncStatus, setSyncStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const fetchFromServer = async () => {
    setSyncStatus('loading');
    try {
      const response = await fetch('/api/inventory');
      if (response.ok) {
        const data = await response.json();
        if (data && Array.isArray(data.items)) {
          setItems(data.items);
          setSyncStatus('success');
          return;
        }
      }
      throw new Error('Server Fetch Failed');
    } catch (err) {
      console.warn('서버 연결 실패. 로컬 데이터를 사용합니다.');
      const savedItems = localStorage.getItem(STORAGE_KEY);
      if (savedItems) setItems(JSON.parse(savedItems));
      setSyncStatus('error');
    }
  };

  const saveToServer = async (data: Item[]) => {
    setSyncStatus('loading');
    try {
      const response = await fetch('/api/inventory', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: data, updatedAt: new Date().toISOString() }),
      });
      if (response.ok) setSyncStatus('success');
      else throw new Error('Server Save Failed');
    } catch (err) {
      setSyncStatus('error');
    }
  };

  useEffect(() => {
    fetchFromServer();
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
    if (items.length > 0) {
      const timer = setTimeout(() => saveToServer(items), 1000);
      return () => clearTimeout(timer);
    }
  }, [items]);

  const stats = useMemo(() => {
    return {
      partCount: items.filter(i => i.type === 'part').length,
      productCount: items.filter(i => i.type === 'product').length,
    };
  }, [items]);

  const allUsedSerials = useMemo(() => {
    const serials: string[] = [];
    items.forEach(item => {
      item.transactions.forEach(t => {
        if (t.serialNumber) serials.push(t.serialNumber.toUpperCase());
      });
    });
    return Array.from(new Set(serials));
  }, [items]);

  const handleLocalExport = async () => {
    const dataObj = { items, version: '2.0', exportDate: new Date().toISOString() };
    const jsonStr = JSON.stringify(dataObj, null, 2);

    if ('showSaveFilePicker' in window) {
      try {
        const handle = await (window as any).showSaveFilePicker({
          suggestedName: `재고관리_백업_${new Date().toISOString().split('T')[0]}.json`,
          types: [{
            description: 'JSON File',
            accept: { 'application/json': ['.json'] },
          }],
        });
        const writable = await handle.createWritable();
        await writable.write(jsonStr);
        await writable.close();
        alert('파일이 지정된 위치에 저장되었습니다.');
        return;
      } catch (err: any) {
        if (err.name === 'AbortError') return;
        console.error('File API Error:', err);
      }
    }

    const blob = new Blob([jsonStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `재고관리_백업_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLocalImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.items && Array.isArray(json.items)) {
          if (confirm('데이터를 복구하시겠습니까? 현재 데이터가 덮어씌워집니다.')) {
            setItems(json.items);
            alert('복구가 완료되었습니다.');
          }
        } else {
          alert('올바른 파일 형식이 아닙니다.');
        }
      } catch (err) {
        alert('파일을 읽는 중 오류가 발생했습니다.');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginPassword === ADMIN_PASSWORD) setAuthRole('admin');
    else if (loginPassword === PRODUCT_ONLY_PASSWORD) setAuthRole('product_only');
    else alert('비밀번호가 틀렸습니다.');
    setLoginPassword('');
  };

  const handleLogout = () => {
    setAuthRole(null);
    setSearchTerm('');
  };

  const handleAddItem = (itemData: Omit<Item, 'id' | 'transactions'>, initialQuantity: number) => {
    const newItem: Item = { ...itemData, id: generateId('item'), transactions: [] };
    if (initialQuantity > 0) {
      newItem.transactions.push({
        id: generateId('t'), type: 'purchase', quantity: initialQuantity,
        date: new Date().toISOString(), remarks: '초기 수량 등록',
      });
    }
    setItems(prev => [newItem, ...prev]);
  };

  const handleDeleteItemConfirm = () => {
    const currentPass = authRole === 'admin' ? ADMIN_PASSWORD : PRODUCT_ONLY_PASSWORD;
    if (deletePassword !== currentPass) {
      alert('비밀번호가 틀렸습니다.');
      return;
    }
    if (itemToDelete) {
      setItems(prev => prev.filter(i => i.id !== itemToDelete.id));
      setItemToDelete(null);
      setDeletePassword('');
    }
  };

  const handleUpdateItem = (itemId: string, updatedData: Partial<Item>) => {
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, ...updatedData } : item));
  };

  const handleAddTransaction = (itemId: string, transaction: Omit<Transaction, 'id'>) => {
    const newTransaction: Transaction = { ...transaction, id: generateId('t') };
    setItems(prev => prev.map(item => {
      if (item.id === itemId) {
        return { ...item, transactions: [...item.transactions, newTransaction] };
      }
      return item;
    }));
  };

  const handleUpdateTransaction = (itemId: string, transactionId: string, updatedData: Partial<Transaction>) => {
    setItems(prev => prev.map(item => {
      if (item.id === itemId) {
        return { ...item, transactions: item.transactions.map(t => t.id === transactionId ? { ...t, ...updatedData } : t) };
      }
      return item;
    }));
  };

  const handleDeleteTransaction = (itemId: string, transactionId: string) => {
    setItems(prev => prev.map(item => {
      if (item.id === itemId) {
        return { ...item, transactions: item.transactions.filter(t => t.id !== transactionId) };
      }
      return item;
    }));
  };

  const selectedItem = useMemo(() => items.find(i => i.id === selectedItemId), [items, selectedItemId]);

  const filteredInventory = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    return items.filter(item => {
        const matchesTab = (activeTab === 'part' && item.type === 'part') || (activeTab === 'product' && item.type === 'product');
        if (!matchesTab) return false;
        const basicMatch = item.name.toLowerCase().includes(term) || item.code.toLowerCase().includes(term);
        if (basicMatch) return true;
        if (activeTab === 'product') return item.transactions.some(t => t.serialNumber?.toLowerCase().includes(term));
        return false;
    });
  }, [items, searchTerm, activeTab]);

  const exportToExcel = () => {
    let csvContent = "\ufeff";
    const headers = activeTab === 'part' ? ['코드', '품명', '도번', '현재재고'] : ['코드', '제품명', '현재재고'];
    csvContent += headers.join(',') + '\r\n';
    filteredInventory.forEach(item => {
      const row = activeTab === 'part' 
        ? [item.code, item.name, item.drawingNumber, calculateStock(item)]
        : [item.code, item.name, calculateStock(item)];
      csvContent += row.map(v => `"${String(v).replace(/"/g, '""')}"`).join(',') + '\r\n';
    });
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `${activeTab === 'part' ? '부품' : '제품'}_재고_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  if (!authRole) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-md p-8 sm:p-12 animate-fade-in-up border border-slate-100">
          <div className="flex flex-col items-center mb-10">
            <div className="bg-indigo-600 p-4 rounded-2xl shadow-lg mb-6">
              <BoxIcon className="w-10 h-10 text-white" />
            </div>
            <h1 className="text-2xl font-black text-slate-800 tracking-tight uppercase text-center">재고 관리 시스템</h1>
          </div>
          <form onSubmit={handleLogin} className="space-y-6">
            <input 
              type="password" autoFocus value={loginPassword}
              onChange={(e) => setLoginPassword(e.target.value)}
              placeholder="PASSWORD"
              className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-600 outline-none text-center text-3xl font-black tracking-[0.5em] transition-all"
            />
            <button type="submit" className="w-full py-4 bg-indigo-600 text-white font-black rounded-xl shadow-xl hover:bg-indigo-700 transition-all text-lg uppercase tracking-widest">로그인</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 font-sans">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-20 shadow-sm">
        <div className="container mx-auto px-4 sm:px-6">
            <div className="flex justify-between items-center py-4">
                <div className="flex items-center space-x-4">
                    <BoxIcon className="h-8 w-8 text-indigo-600" />
                    <h1 className="text-2xl font-bold text-slate-900 tracking-tight uppercase">재고 관리 시스템</h1>
                </div>

                <div className="flex flex-col items-end space-y-1.5">
                  <div className="flex items-center space-x-2">
                    <div className={`flex items-center space-x-2 px-2.5 py-1 rounded-full border transition-all ${syncStatus === 'success' ? 'bg-emerald-50 border-emerald-100' : 'bg-slate-50 border-slate-100'}`}>
                      <div className={`w-2 h-2 rounded-full ${syncStatus === 'success' ? 'bg-emerald-500' : syncStatus === 'loading' ? 'bg-amber-500 animate-pulse' : 'bg-slate-300'}`}></div>
                      <span className={`text-[9px] font-black uppercase tracking-widest ${syncStatus === 'success' ? 'text-emerald-600' : 'text-slate-400'}`}>
                          {syncStatus === 'success' ? 'Synced' : syncStatus === 'loading' ? 'Syncing' : 'Local Mode'}
                      </span>
                    </div>
                    <button onClick={handleLogout} className="px-3 py-1 bg-slate-100 text-slate-500 rounded-md hover:bg-slate-200 transition-colors font-black text-[9px] uppercase">Logout</button>
                  </div>

                  <div className="flex items-center space-x-2">
                    <button onClick={handleLocalExport} className="flex items-center gap-1.5 px-2.5 py-1 bg-slate-100 text-slate-500 border border-slate-200 rounded-md hover:bg-slate-200 transition-all text-[9px] font-black uppercase tracking-wider">
                        <DownloadIcon className="w-2.5 h-2.5" />
                        <span>내보내기</span>
                    </button>
                    <label className="flex items-center gap-1.5 px-2.5 py-1 bg-slate-100 text-slate-500 border border-slate-200 rounded-md hover:bg-slate-200 transition-all text-[9px] font-black cursor-pointer uppercase tracking-wider">
                        <CloudIcon className="w-2.5 h-2.5" />
                        <span>가져오기</span>
                        <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleLocalImport} />
                    </label>
                  </div>
                </div>
            </div>

            <div className="flex space-x-12 -mb-px">
                {authRole === 'admin' && (
                  <button onClick={() => setActiveTab('part')} className={`pb-4 px-2 text-lg font-black uppercase tracking-widest transition-all border-b-4 ${activeTab === 'part' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                    부품 재고관리 ({stats.partCount})
                  </button>
                )}
                <button onClick={() => setActiveTab('product')} className={`pb-4 px-2 text-lg font-black uppercase tracking-widest transition-all border-b-4 ${activeTab === 'product' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                  제품 재고관리 ({stats.productCount})
                </button>
            </div>
        </div>
      </header>

      <main className="container mx-auto p-4 sm:p-8">
        <div className="flex flex-col xl:flex-row xl:justify-between xl:items-center gap-6 mb-10">
          <div className="relative flex-grow max-w-3xl">
              <span className="absolute inset-y-0 left-0 flex items-center pl-5"><SearchIcon className="text-slate-400 w-6 h-6" /></span>
              <input
                  type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value.toUpperCase())}
                  placeholder="품명, 코드, 일련번호 검색..."
                  className="w-full pl-14 pr-6 py-4 border-2 border-slate-100 rounded-2xl focus:outline-none focus:border-indigo-400 bg-white shadow-sm font-bold text-lg transition-all"
              />
          </div>
          <div className="flex flex-wrap gap-3">
            <button onClick={exportToExcel} className="flex items-center gap-2 px-8 py-4 bg-emerald-600 text-white font-black rounded-xl shadow-lg hover:bg-emerald-700 transition-all text-base uppercase tracking-widest">
                <ServerIcon className="w-5 h-5" />
                <span>엑셀 파일 저장</span>
            </button>
            <button onClick={() => setShowAddItemModal(true)} className="flex items-center gap-2 px-10 py-4 bg-indigo-600 text-white font-black rounded-xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all text-base uppercase tracking-widest">
                <PlusIcon className="w-6 h-6" />
                <span>신규 등록</span>
            </button>
          </div>
        </div>

        <div className="bg-white shadow-2xl border border-slate-100 rounded-[2.5rem] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="text-sm text-slate-400 uppercase bg-slate-50/50 border-b border-slate-100 font-black tracking-[0.2em]">
                <tr>
                  <th className="px-10 py-7">품목 코드</th>
                  <th className="px-10 py-7">품명 / 제품명</th>
                  {activeTab === 'part' && <th className="px-10 py-7">도번</th>}
                  <th className="px-10 py-7 text-right">현재 재고수량</th>
                  <th className="px-10 py-7 text-center">관리</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {filteredInventory.length === 0 ? (
                  <tr><td colSpan={activeTab === 'part' ? 5 : 4} className="px-10 py-24 text-center text-slate-300 font-black uppercase tracking-widest italic text-2xl">기록된 데이터가 없습니다</td></tr>
                ) : (
                  filteredInventory.map(item => {
                    const stock = calculateStock(item);
                    return (
                      <tr key={item.id} className="hover:bg-indigo-50/30 transition-colors group">
                        <td className="px-10 py-7 font-mono text-indigo-600 font-black text-xl">{item.code}</td>
                        <td className="px-10 py-7 font-black text-slate-800 text-xl">{item.name}</td>
                        {activeTab === 'part' && <td className="px-10 py-7 text-slate-400 font-mono text-sm uppercase font-bold">{item.drawingNumber || '-'}</td>}
                        <td className="px-10 py-7 text-right">
                            <span className={`text-4xl font-black ${stock > 0 ? 'text-slate-900' : 'text-rose-500 animate-pulse'}`}>
                                {stock.toLocaleString()} <span className="text-xs uppercase text-slate-400 ml-1">EA</span>
                            </span>
                        </td>
                        <td className="px-10 py-7">
                          <div className="flex justify-center gap-4">
                            <button onClick={() => setSelectedItemId(item.id)} className="px-6 py-3 bg-indigo-50 text-indigo-600 rounded-xl font-black text-sm uppercase tracking-wider hover:bg-indigo-600 hover:text-white transition-all shadow-sm">상세</button>
                            <button onClick={() => setItemToDelete({id: item.id, type: 'inventory'})} className="p-3 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-2xl transition-all"><TrashIcon className="w-7 h-7" /></button>
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>
      </main>

      {itemToDelete && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[60] flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] p-10 max-w-md w-full shadow-2xl border border-slate-100 animate-fade-in-up">
                <div className="flex flex-col items-center mb-8">
                    <div className="p-5 bg-rose-50 rounded-[1.5rem] mb-6"><TrashIcon className="w-12 h-12 text-rose-500" /></div>
                    <h4 className="text-2xl font-black text-slate-800 uppercase tracking-tight">삭제 비밀번호</h4>
                    <p className="text-xs text-slate-400 font-bold mt-2 uppercase tracking-widest">정말로 삭제하시겠습니까?</p>
                </div>
                <input type="password" autoFocus value={deletePassword} onChange={(e) => setDeletePassword(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleDeleteItemConfirm()} placeholder="PASSWORD" className="w-full px-6 py-5 border-2 border-slate-100 rounded-2xl focus:border-rose-500 outline-none mb-8 text-center text-3xl font-black tracking-widest" />
                <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => setItemToDelete(null)} className="py-4 bg-slate-100 text-slate-600 rounded-xl font-black uppercase text-xs tracking-widest">취소</button>
                    <button onClick={handleDeleteItemConfirm} className="py-4 bg-rose-600 text-white rounded-xl font-black uppercase text-xs tracking-widest shadow-lg shadow-rose-100">삭제 확정</button>
                </div>
            </div>
        </div>
      )}

      {showAddItemModal && (
        <AddItemModal onAddItem={handleAddItem} onClose={() => setShowAddItemModal(false)} existingCodes={items.map(i => i.code)} defaultType={activeTab === 'product' ? 'product' : 'part'} />
      )}
      {selectedItemId && selectedItem && (
        <ItemDetailModal 
          item={selectedItem} 
          authRole={authRole as any} 
          allUsedSerials={allUsedSerials} 
          existingCodes={items.map(i => i.code)}
          onAddTransaction={handleAddTransaction} 
          onUpdateTransaction={handleUpdateTransaction} 
          onDeleteTransaction={handleDeleteTransaction} 
          onUpdateItem={handleUpdateItem} 
          onClose={() => setSelectedItemId(null)} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import type { Item, Transaction } from './types';
import AddItemModal from './components/AddItemModal';
import ItemDetailModal from './components/ItemDetailModal';
import { PlusIcon, BoxIcon, SearchIcon, TrashIcon, DownloadIcon, CloudIcon, ServerIcon } from './components/icons';

const STORAGE_KEY = 'inventory_system_data_v2';
const ADMIN_PASSWORD = '0000';
const PRODUCT_ONLY_PASSWORD = '1111';

const generateId = (prefix: string) => `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

const calculateStock = (item: Item): number => {
  return item.transactions.reduce((acc, t) => {
    return t.type === 'purchase' ? acc + t.quantity : acc - t.quantity;
  }, 0);
};

const App: React.FC = () => {
  const [authRole, setAuthRole] = useState<'admin' | 'product_only' | null>(null);
  const [loginPassword, setLoginPassword] = useState('');
  const [activeTab, setActiveTab] = useState<'part' | 'product'>('part');

  const [items, setItems] = useState<Item[]>([]);
  const [showAddItemModal, setShowAddItemModal] = useState(false);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<{id: string, type: 'inventory'} | null>(null);
  const [deletePassword, setDeletePassword] = useState('');

  const [syncStatus, setSyncStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const fetchFromServer = async () => {
    setSyncStatus('loading');
    try {
      const response = await fetch('/api/inventory');
      if (response.ok) {
        const data = await response.json();
        if (data && Array.isArray(data.items)) {
          setItems(data.items);
          setSyncStatus('success');
          return;
        }
      }
      throw new Error('Server Fetch Failed');
    } catch (err) {
      const savedItems = localStorage.getItem(STORAGE_KEY);
      if (savedItems) setItems(JSON.parse(savedItems));
      setSyncStatus('error');
    }
  };

  const saveToServer = async (data: Item[]) => {
    setSyncStatus('loading');
    try {
      const response = await fetch('/api/inventory', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: data, updatedAt: new Date().toISOString() }),
      });
      if (response.ok) setSyncStatus('success');
      else throw new Error('Server Save Failed');
    } catch (err) {
      setSyncStatus('error');
    }
  };

  useEffect(() => {
    fetchFromServer();
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
    if (items.length > 0) {
      const timer = setTimeout(() => saveToServer(items), 1500);
      return () => clearTimeout(timer);
    }
  }, [items]);

  const stats = useMemo(() => {
    return {
      partCount: items.filter(i => i.type === 'part').length,
      productCount: items.filter(i => i.type === 'product').length,
    };
  }, [items]);

  const allUsedSerials = useMemo(() => {
    const serials: string[] = [];
    items.forEach(item => {
      item.transactions.forEach(t => {
        if (t.serialNumber) serials.push(t.serialNumber.toUpperCase());
      });
    });
    return Array.from(new Set(serials));
  }, [items]);

  const handleLocalExport = async () => {
    const dataObj = { items, version: '2.0', exportDate: new Date().toISOString() };
    const jsonStr = JSON.stringify(dataObj, null, 2);
    const blob = new Blob([jsonStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `재고관리_백업_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLocalImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.items && Array.isArray(json.items)) {
          if (confirm('데이터를 복구하시겠습니까?')) {
            setItems(json.items);
          }
        }
      } catch (err) { alert('파일 오류'); }
    };
    reader.readAsText(file);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginPassword === ADMIN_PASSWORD) setAuthRole('admin');
    else if (loginPassword === PRODUCT_ONLY_PASSWORD) setAuthRole('product_only');
    else alert('비밀번호 오류');
    setLoginPassword('');
  };

  const handleLogout = () => { setAuthRole(null); setSearchTerm(''); };

  const handleAddItem = (itemData: Omit<Item, 'id' | 'transactions'>, initialQuantity: number) => {
    const newItem: Item = { ...itemData, id: generateId('item'), transactions: [] };
    if (initialQuantity > 0) {
      newItem.transactions.push({
        id: generateId('t'), type: 'purchase', quantity: initialQuantity,
        date: new Date().toISOString(), remarks: '초기 등록',
      });
    }
    setItems(prev => [newItem, ...prev]);
  };

  const handleDeleteItemConfirm = () => {
    if (itemToDelete) {
      setItems(prev => prev.filter(i => i.id !== itemToDelete.id));
      setItemToDelete(null);
      setDeletePassword('');
    }
  };

  const handleUpdateItem = (itemId: string, updatedData: Partial<Item>) => {
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, ...updatedData } : item));
  };

  const handleAddTransaction = (itemId: string, transaction: Omit<Transaction, 'id'>) => {
    const newTransaction: Transaction = { ...transaction, id: generateId('t') };
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, transactions: [...item.transactions, newTransaction] } : item));
  };

  const handleUpdateTransaction = (itemId: string, transactionId: string, updatedData: Partial<Transaction>) => {
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, transactions: item.transactions.map(t => t.id === transactionId ? { ...t, ...updatedData } : t) } : item));
  };

  const handleDeleteTransaction = (itemId: string, transactionId: string) => {
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, transactions: item.transactions.filter(t => t.id !== transactionId) } : item));
  };

  const selectedItem = useMemo(() => items.find(i => i.id === selectedItemId), [items, selectedItemId]);

  const filteredInventory = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    return items.filter(item => {
        const matchesTab = (activeTab === 'part' && item.type === 'part') || (activeTab === 'product' && item.type === 'product');
        if (!matchesTab) return false;
        return item.name.toLowerCase().includes(term) || item.code.toLowerCase().includes(term) || item.modelName?.toLowerCase().includes(term);
    });
  }, [items, searchTerm, activeTab]);

  const exportToExcel = () => {
    let csvContent = "\ufeff코드,품명,기종,현재재고\r\n";
    filteredInventory.forEach(item => {
      csvContent += `${item.code},${item.name},${item.modelName || ''},${calculateStock(item)}\r\n`;
    });
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `재고현황_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  if (!authRole) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xs p-8 animate-fade-in-up border border-slate-100">
          <div className="flex flex-col items-center mb-6">
            <div className="bg-indigo-600 p-3 rounded-xl shadow-lg mb-4">
              <BoxIcon className="w-8 h-8 text-white" />
            </div>
            <h1 className="text-xl font-black text-slate-800 tracking-tight uppercase text-center">재고 관리 시스템</h1>
          </div>
          <form onSubmit={handleLogin} className="space-y-4">
            <input 
              type="password" autoFocus value={loginPassword}
              onChange={(e) => setLoginPassword(e.target.value)}
              placeholder="PASSWORD"
              className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-100 rounded-xl focus:border-indigo-600 outline-none text-center text-2xl font-black tracking-[0.4em] transition-all"
            />
            <button type="submit" className="w-full py-3.5 bg-indigo-600 text-white font-black rounded-lg shadow-lg hover:bg-indigo-700 transition-all text-sm uppercase tracking-widest">로그인</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 font-sans">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-20 shadow-sm">
        <div className="container mx-auto px-4 sm:px-6">
