  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.code || !formData.name) return;
    const { initialQuantity, ...rest } = formData;
    onAddItem({ ...rest, type: itemType }, parseInt(initialQuantity, 10) || 0);
