            <button type="button" onClick={() => setItemType('part')} className={`flex-1 py-2 text-xs font-black rounded ${itemType === 'part' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>부품</button>
            <button type="button" onClick={() => setItemType('product')} className={`flex-1 py-2 text-xs font-black rounded ${itemType === 'product' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>제품</button>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">날짜</label>
              <input type="date" name="registrationDate" value={formData.registrationDate} onChange={handleChange} className="w-full px-3 py-2 border rounded-lg font-bold" />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">코드 접두어</label>
              <input type="text" value={prefix} onChange={(e) => setPrefix(e.target.value.toUpperCase())} className="w-full px-3 py-2 border rounded-lg font-black" placeholder="예: PT" />
            </div>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">품번 (코드)</label>
            <input type="text" name="code" value={formData.code} onChange={handleChange} className="w-full px-3 py-2 border rounded-lg font-black text-indigo-600" required />
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">품명 / 제품명</label>
            <input type="text" name="name" value={formData.name} onChange={handleChange} className="w-full px-3 py-2 border rounded-lg font-black" required />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">기종</label>
              <input type="text" name="modelName" value={formData.modelName} onChange={handleChange} className="w-full px-3 py-2 border rounded-lg font-bold" />
