            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">도번</label>
              <input type="text" name="drawingNumber" value={formData.drawingNumber} onChange={handleChange} className="w-full px-3 py-2 border rounded-lg font-mono font-bold" />
