// 이 파일은 Vercel 환경에서 자동으로 백엔드 API 서버 역할을 합니다.
export const config = {
  runtime: 'edge',
};

export default async function handler(req: Request) {
  const url = process.env.KV_REST_API_URL;
  const token = process.env.KV_REST_API_TOKEN;

  if (!url || !token) {
    return new Response(JSON.stringify({ error: 'Upstash credentials missing' }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  const key = 'inventory_data';

  try {
    if (req.method === 'GET') {
      const response = await fetch(`${url}/get/${key}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      const items = data.result ? JSON.parse(data.result) : { items: [] };
      return new Response(JSON.stringify(items), {
        headers: { 'Content-Type': 'application/json' },
      });
    }

    if (req.method === 'POST') {
      const body = await req.json();
      await fetch(`${url}/set/${key}`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
        body: JSON.stringify(JSON.stringify(body)),
      });
      return new Response(JSON.stringify({ success: true }), {
        headers: { 'Content-Type': 'application/json' },
      });
    }

    return new Response('Method Not Allowed', { status: 405 });
  } catch (err) {
    return new Response(JSON.stringify({ error: err.message }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' },
    });
  }
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import type { Item, Transaction } from './types';
import AddItemModal from './components/AddItemModal';
import ItemDetailModal from './components/ItemDetailModal';
import { PlusIcon, BoxIcon, SearchIcon, TrashIcon, DownloadIcon, CloudIcon, ServerIcon } from './components/icons';

const STORAGE_KEY = 'inventory_system_data_v2';
const ADMIN_PASSWORD = '0000';
const PRODUCT_ONLY_PASSWORD = '1111';
const DB_KEY = 'inventory_data_v2';

// Upstash 설정 (환경변수에서 직접 가져옴)
const KV_URL = (process.env as any).KV_REST_API_URL;
const KV_TOKEN = (process.env as any).KV_REST_API_TOKEN;

const generateId = (prefix: string) => `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

const calculateStock = (item: Item): number => {
  return item.transactions.reduce((acc, t) => {
    return t.type === 'purchase' ? acc + t.quantity : acc - t.quantity;
  }, 0);
};

const App: React.FC = () => {
  const [authRole, setAuthRole] = useState<'admin' | 'product_only' | null>(null);
  const [loginPassword, setLoginPassword] = useState('');
  const [activeTab, setActiveTab] = useState<'part' | 'product'>('part');

  const [items, setItems] = useState<Item[]>([]);
  const [showAddItemModal, setShowAddItemModal] = useState(false);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<{id: string, type: 'inventory'} | null>(null);
  const [deletePassword, setDeletePassword] = useState('');

  const [syncStatus, setSyncStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Upstash에서 데이터 가져오기
  const fetchFromServer = async () => {
    if (!KV_URL || !KV_TOKEN) {
      console.warn('DB 설정이 없습니다. 로컬 모드로 동작합니다.');
      setSyncStatus('error');
      const savedItems = localStorage.getItem(STORAGE_KEY);
      if (savedItems) setItems(JSON.parse(savedItems));
      return;
    }

    setSyncStatus('loading');
    try {
      const response = await fetch(`${KV_URL}/get/${DB_KEY}`, {
        headers: { Authorization: `Bearer ${KV_TOKEN}` },
      });
      const data = await response.json();
      if (data.result) {
        const parsed = JSON.parse(data.result);
        setItems(parsed.items || []);
        setSyncStatus('success');
      } else {
        // 데이터가 없는 경우 로컬 스토리지 확인
        const savedItems = localStorage.getItem(STORAGE_KEY);
        if (savedItems) setItems(JSON.parse(savedItems));
        setSyncStatus('idle');
      }
    } catch (err) {
      console.error('DB Fetch Error:', err);
      setSyncStatus('error');
      const savedItems = localStorage.getItem(STORAGE_KEY);
      if (savedItems) setItems(JSON.parse(savedItems));
    }
  };

  // Upstash에 데이터 저장하기
  const saveToServer = async (data: Item[]) => {
    if (!KV_URL || !KV_TOKEN) return;

    setSyncStatus('loading');
    try {
      const payload = JSON.stringify({ items: data, updatedAt: new Date().toISOString() });
      const response = await fetch(`${KV_URL}/set/${DB_KEY}`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${KV_TOKEN}` },
        body: JSON.stringify(payload),
      });
      if (response.ok) setSyncStatus('success');
      else throw new Error('DB Save Failed');
    } catch (err) {
      console.error('DB Save Error:', err);
      setSyncStatus('error');
    }
  };

  useEffect(() => {
    fetchFromServer();
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
    if (items.length > 0) {
      const timer = setTimeout(() => saveToServer(items), 2000);
      return () => clearTimeout(timer);
    }
  }, [items]);

  const stats = useMemo(() => {
    return {
      partCount: items.filter(i => i.type === 'part').length,
      productCount: items.filter(i => i.type === 'product').length,
    };
  }, [items]);

  const allUsedSerials = useMemo(() => {
    const serials: string[] = [];
    items.forEach(item => {
      item.transactions.forEach(t => {
        if (t.serialNumber) serials.push(t.serialNumber.toUpperCase());
      });
    });
    return Array.from(new Set(serials));
  }, [items]);

  const handleLocalExport = async () => {
    const dataObj = { items, version: '2.0', exportDate: new Date().toISOString() };
    const jsonStr = JSON.stringify(dataObj, null, 2);
    const blob = new Blob([jsonStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `재고관리_백업_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLocalImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.items && Array.isArray(json.items)) {
          if (confirm('데이터를 복구하시겠습니까? 현재 데이터가 덮어씌워집니다.')) {
            setItems(json.items);
            alert('복구가 완료되었습니다.');
          }
        }
      } catch (err) { alert('파일 오류'); }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginPassword === ADMIN_PASSWORD) setAuthRole('admin');
    else if (loginPassword === PRODUCT_ONLY_PASSWORD) setAuthRole('product_only');
    else alert('비밀번호가 틀렸습니다.');
    setLoginPassword('');
  };

  const handleLogout = () => { setAuthRole(null); setSearchTerm(''); };

  const handleAddItem = (itemData: Omit<Item, 'id' | 'transactions'>, initialQuantity: number) => {
    const newItem: Item = { ...itemData, id: generateId('item'), transactions: [] };
    if (initialQuantity > 0) {
      newItem.transactions.push({
        id: generateId('t'), type: 'purchase', quantity: initialQuantity,
        date: new Date().toISOString(), remarks: '초기 수량 등록',
      });
    }
    setItems(prev => [newItem, ...prev]);
  };

  const handleDeleteItemConfirm = () => {
    const currentPass = authRole === 'admin' ? ADMIN_PASSWORD : PRODUCT_ONLY_PASSWORD;
    if (deletePassword !== currentPass) { alert('비밀번호 오류'); return; }
    if (itemToDelete) {
      setItems(prev => prev.filter(i => i.id !== itemToDelete.id));
      setItemToDelete(null);
      setDeletePassword('');
    }
  };

  const handleUpdateItem = (itemId: string, updatedData: Partial<Item>) => {
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, ...updatedData } : item));
  };

  const handleAddTransaction = (itemId: string, transaction: Omit<Transaction, 'id'>) => {
    const newTransaction: Transaction = { ...transaction, id: generateId('t') };
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, transactions: [...item.transactions, newTransaction] } : item));
  };

  const handleUpdateTransaction = (itemId: string, transactionId: string, updatedData: Partial<Transaction>) => {
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, transactions: item.transactions.map(t => t.id === transactionId ? { ...t, ...updatedData } : t) } : item));
  };

  const handleDeleteTransaction = (itemId: string, transactionId: string) => {
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, transactions: item.transactions.filter(t => t.id !== transactionId) } : item));
  };

  const selectedItem = useMemo(() => items.find(i => i.id === selectedItemId), [items, selectedItemId]);

  const filteredInventory = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    return items.filter(item => {
        const matchesTab = (activeTab === 'part' && item.type === 'part') || (activeTab === 'product' && item.type === 'product');
        if (!matchesTab) return false;
        return (
          item.name.toLowerCase().includes(term) || 
          item.code.toLowerCase().includes(term) || 
          (item.modelName && item.modelName.toLowerCase().includes(term))
        );
    });
  }, [items, searchTerm, activeTab]);

  const exportToExcel = () => {
    let csvContent = "\ufeff코드,품명,기종,현재재고\r\n";
    filteredInventory.forEach(item => {
      csvContent += `"${item.code}","${item.name}","${item.modelName || ''}",${calculateStock(item)}\r\n`;
    });
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `재고현황_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  if (!authRole) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xs p-8 animate-fade-in-up border border-slate-100">
          <div className="flex flex-col items-center mb-8">
            <div className="bg-indigo-600 p-3 rounded-xl shadow-lg mb-4">
              <BoxIcon className="w-8 h-8 text-white" />
            </div>
            <h1 className="text-xl font-black text-slate-800 tracking-tight uppercase text-center">재고 관리 시스템</h1>
          </div>
          <form onSubmit={handleLogin} className="space-y-4">
            <input 
              type="password" autoFocus value={loginPassword}
              onChange={(e) => setLoginPassword(e.target.value)}
              placeholder="PASSWORD"
              className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-100 rounded-xl focus:border-indigo-600 outline-none text-center text-2xl font-black tracking-[0.4em] transition-all"
            />
            <button type="submit" className="w-full py-3.5 bg-indigo-600 text-white font-black rounded-lg shadow-lg hover:bg-indigo-700 transition-all text-sm uppercase tracking-widest">로그인</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 font-sans">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-20 shadow-sm">
        <div className="container mx-auto px-4 sm:px-6">
            <div className="flex justify-between items-center py-4">
                <div className="flex items-center space-x-3">
                    <BoxIcon className="h-7 w-7 text-indigo-600" />
                    <h1 className="text-xl font-bold text-slate-900 tracking-tight uppercase">Inventory Management</h1>
                </div>

                <div className="flex flex-col items-end space-y-1">
                  <div className="flex items-center space-x-2">
                    <div className={`flex items-center space-x-1.5 px-2 py-0.5 rounded-full border transition-all ${syncStatus === 'success' ? 'bg-emerald-50 border-emerald-100' : 'bg-slate-50 border-slate-100'}`}>
                      <div className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'success' ? 'bg-emerald-500' : syncStatus === 'loading' ? 'bg-amber-500 animate-pulse' : 'bg-slate-300'}`}></div>
                      <span className={`text-[8px] font-black uppercase tracking-widest ${syncStatus === 'success' ? 'text-emerald-600' : 'text-slate-400'}`}>
                          {syncStatus === 'success' ? 'Cloud' : syncStatus === 'loading' ? 'Sync' : 'Local'}
                      </span>
                    </div>
                    <button onClick={handleLogout} className="px-2 py-0.5 bg-slate-100 text-slate-500 rounded border border-slate-200 hover:bg-slate-200 transition-colors font-black text-[9px] uppercase">Logout</button>
                  </div>

                  <div className="flex items-center space-x-2">
                    <button onClick={handleLocalExport} className="flex items-center gap-1 px-2 py-0.5 bg-slate-100 text-slate-500 border border-slate-200 rounded hover:bg-slate-200 transition-all text-[9px] font-black uppercase tracking-wider">
                        <DownloadIcon className="w-2.5 h-2.5" />
                        <span>내보내기</span>
                    </button>
                    <label className="flex items-center gap-1 px-2 py-0.5 bg-slate-100 text-slate-500 border border-slate-200 rounded hover:bg-slate-200 transition-all text-[9px] font-black cursor-pointer uppercase tracking-wider">
                        <CloudIcon className="w-2.5 h-2.5" />
                        <span>가져오기</span>
                        <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleLocalImport} />
                    </label>
                  </div>
                </div>
            </div>

            <div className="flex space-x-8 -mb-px">
                {authRole === 'admin' && (
                  <button onClick={() => setActiveTab('part')} className={`pb-3 px-1 text-sm font-black uppercase tracking-widest transition-all border-b-2 ${activeTab === 'part' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                    부품 재고관리 ({stats.partCount})
                  </button>
                )}
                <button onClick={() => setActiveTab('product')} className={`pb-3 px-1 text-sm font-black uppercase tracking-widest transition-all border-b-2 ${activeTab === 'product' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                  제품 재고관리 ({stats.productCount})
                </button>
            </div>
        </div>
      </header>

      <main className="container mx-auto p-4 sm:p-6">
        <div className="flex flex-col md:flex-row md:justify-between md:items-center gap-4 mb-8">
          <div className="relative flex-grow max-w-xl">
              <span className="absolute inset-y-0 left-0 flex items-center pl-4"><SearchIcon className="text-slate-400 w-5 h-5" /></span>
              <input
                  type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value.toUpperCase())}
                  placeholder="품명, 코드, 기종 검색..."
                  className="w-full pl-12 pr-4 py-3 border-2 border-slate-100 rounded-xl focus:outline-none focus:border-indigo-400 bg-white shadow-sm font-bold text-sm transition-all"
              />
          </div>
          <div className="flex gap-2">
            <button onClick={exportToExcel} className="flex items-center gap-1.5 px-5 py-3 bg-emerald-600 text-white font-black rounded-lg shadow-md hover:bg-emerald-700 text-xs uppercase tracking-widest">
                <ServerIcon className="w-4 h-4" />
                <span>엑셀 파일 저장</span>
            </button>
            <button onClick={() => setShowAddItemModal(true)} className="flex items-center gap-1.5 px-6 py-3 bg-indigo-600 text-white font-black rounded-lg shadow-lg hover:bg-indigo-700 text-xs uppercase tracking-widest">
                <PlusIcon className="w-4 h-4" />
                <span>신규 등록</span>
            </button>
          </div>
        </div>

        <div className="bg-white shadow-xl border border-slate-100 rounded-[1.5rem] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="text-[10px] text-slate-400 uppercase bg-slate-50/50 border-b border-slate-100 font-black tracking-[0.2em]">
                <tr>
                  <th className="px-6 py-4">코드</th>
                  <th className="px-6 py-4">품명 / 제품명</th>
                  <th className="px-6 py-4">기종</th>
                  {activeTab === 'part' && <th className="px-6 py-4">도번</th>}
                  <th className="px-6 py-4 text-right">현재 재고</th>
                  <th className="px-6 py-4 text-center">관리</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {filteredInventory.length === 0 ? (
                  <tr><td colSpan={6} className="px-6 py-20 text-center text-slate-300 font-black uppercase tracking-widest italic">기록된 데이터가 없습니다</td></tr>
                ) : (
                  filteredInventory.map(item => {
                    const stock = calculateStock(item);
                    return (
                      <tr key={item.id} className="hover:bg-indigo-50/20 transition-colors group">
                        <td className="px-6 py-4 font-mono text-indigo-600 font-black text-sm">{item.code}</td>
                        <td className="px-6 py-4 font-black text-slate-800 text-sm">{item.name}</td>
                        <td className="px-6 py-4 text-slate-500 font-bold text-xs">{item.modelName || '-'}</td>
                        {activeTab === 'part' && <td className="px-6 py-4 text-slate-400 font-mono text-xs font-bold uppercase">{item.drawingNumber || '-'}</td>}
                        <td className="px-6 py-4 text-right">
                            <span className={`text-xl font-black ${stock > 0 ? 'text-slate-900' : 'text-rose-500 animate-pulse'}`}>
                                {stock.toLocaleString()} <span className="text-[10px] text-slate-400 ml-0.5">EA</span>
                            </span>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex justify-center gap-2">
                            <button onClick={() => setSelectedItemId(item.id)} className="px-3 py-1.5 bg-indigo-50 text-indigo-600 rounded-md font-black text-[10px] uppercase hover:bg-indigo-600 hover:text-white transition-all shadow-sm">상세</button>
                            <button onClick={() => setItemToDelete({id: item.id, type: 'inventory'})} className="p-1.5 text-slate-300 hover:text-rose-600 transition-all"><TrashIcon className="w-5 h-5" /></button>
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>
      </main>

      {itemToDelete && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl p-8 max-w-xs w-full shadow-2xl border border-slate-100 animate-fade-in-up">
                <h4 className="text-xl font-black text-slate-800 mb-2 uppercase tracking-tight text-center">삭제 비밀번호</h4>
                <input type="password" autoFocus value={deletePassword} onChange={(e) => setDeletePassword(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleDeleteItemConfirm()} placeholder="PASSWORD" className="w-full px-4 py-3 border-2 border-slate-100 rounded-xl focus:border-rose-500 outline-none mb-6 text-center text-2xl font-black tracking-widest" />
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => setItemToDelete(null)} className="py-2.5 bg-slate-100 text-slate-600 rounded-lg font-black uppercase text-[10px] tracking-widest">취소</button>
                    <button onClick={handleDeleteItemConfirm} className="py-2.5 bg-rose-600 text-white rounded-lg font-black uppercase text-[10px] tracking-widest">삭제</button>
                </div>
            </div>
        </div>
      )}

      {showAddItemModal && (
        <AddItemModal onAddItem={handleAddItem} onClose={() => setShowAddItemModal(false)} existingCodes={items.map(i => i.code)} defaultType={activeTab === 'product' ? 'product' : 'part'} />
      )}
      {selectedItemId && selectedItem && (
        <ItemDetailModal 
          item={selectedItem} 
          authRole={authRole as any} 
          allUsedSerials={allUsedSerials} 
          existingCodes={items.map(i => i.code)}
          onAddTransaction={handleAddTransaction} 
          onUpdateTransaction={handleUpdateTransaction} 
          onDeleteTransaction={handleDeleteTransaction} 
          onUpdateItem={handleUpdateItem} 
          onClose={() => setSelectedItemId(null)} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import type { Item } from '../types';
import { CloseIcon } from './icons';

interface AddItemModalProps {
  onAddItem: (item: Omit<Item, 'id' | 'transactions'>, initialQuantity: number) => void;
  onClose: () => void;
  existingCodes: string[];
  defaultType: 'part' | 'product';
}

const AddItemModal: React.FC<AddItemModalProps> = ({ onAddItem, onClose, existingCodes, defaultType }) => {
  const [prefix, setPrefix] = useState('');
  const [itemType, setItemType] = useState<'part' | 'product'>(defaultType);
  const [formData, setFormData] = useState({
    registrationDate: new Date().toISOString().split('T')[0],
    code: '',
    name: '',
    drawingNumber: '',
    spec: '',
    modelName: '',
    application: '',
    remarks: '',
    initialQuantity: '0'
  });

  useEffect(() => {
    const upperPrefix = prefix.toUpperCase();
    if (!upperPrefix.trim()) {
      setFormData(prev => ({ ...prev, code: '' }));
      return;
    }
    const regex = new RegExp(`^${upperPrefix}(\\d+)$`);
    let maxNum = 0;
    existingCodes.forEach(code => {
      if (!code) return;
      const match = code.toUpperCase().match(regex);
      if (match) {
        const num = parseInt(match[1], 10);
        if (num > maxNum) maxNum = num;
      }
    });
    setFormData(prev => ({ ...prev, code: `${upperPrefix}${maxNum + 1}` }));
  }, [prefix, existingCodes]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    const processedValue = (name === 'code' || name === 'name') ? value.toUpperCase() : value;
    setFormData(prev => ({ ...prev, [name]: processedValue }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.code || !formData.name) return;
    const { initialQuantity, ...rest } = formData;
    onAddItem({ ...rest, type: itemType }, parseInt(initialQuantity, 10) || 0);
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex justify-center items-center z-50 p-4 font-sans">
      <div className="bg-white rounded-[1.5rem] shadow-2xl w-full max-w-lg animate-fade-in-up overflow-hidden">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight">신규 {itemType === 'part' ? '부품' : '제품'} 등록</h2>
          <button onClick={onClose} className="p-2 text-slate-400 hover:text-slate-800 transition-colors">
            <CloseIcon className="w-6 h-6" />
          </button>
        </div>
        <form onSubmit={handleSubmit} className="p-6 space-y-4 max-h-[85vh] overflow-y-auto">
          <div className="flex p-1 bg-slate-100 rounded-xl">
            <button type="button" onClick={() => setItemType('part')} className={`flex-1 py-2 text-xs font-black rounded-lg transition-all ${itemType === 'part' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>부품</button>
            <button type="button" onClick={() => setItemType('product')} className={`flex-1 py-2 text-xs font-black rounded-lg transition-all ${itemType === 'product' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>제품</button>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">날짜</label>
              <input type="date" name="registrationDate" value={formData.registrationDate} onChange={handleChange} className="w-full px-3 py-2 border rounded-lg font-bold" />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">코드 접두어</label>
              <input type="text" value={prefix} onChange={(e) => setPrefix(e.target.value.toUpperCase())} className="w-full px-3 py-2 border rounded-lg font-black" placeholder="PT" />
            </div>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">품번 (코드)</label>
            <input type="text" name="code" value={formData.code} onChange={handleChange} className="w-full px-4 py-2 bg-indigo-50 border-2 border-indigo-100 rounded-lg font-black text-indigo-600 text-lg outline-none focus:border-indigo-500" required />
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">품명 / 제품명</label>
            <input type="text" name="name" value={formData.name} onChange={handleChange} className="w-full px-4 py-2 border-2 rounded-lg font-black text-slate-800 outline-none focus:border-indigo-500" required />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">기종</label>
              <input type="text" name="modelName" value={formData.modelName} onChange={handleChange} className="w-full px-3 py-2 border rounded-lg font-bold" placeholder="기종명" />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">도번</label>
              <input type="text" name="drawingNumber" value={formData.drawingNumber} onChange={handleChange} className="w-full px-3 py-2 border rounded-lg font-mono font-bold" placeholder="도면번호" />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">적용</label>
              <input type="text" name="application" value={formData.application} onChange={handleChange} className="w-full px-3 py-2 border rounded-lg font-bold" placeholder="적용분야" />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">초기 수량</label>
              <input type="number" name="initialQuantity" value={formData.initialQuantity} onChange={handleChange} className="w-full px-3 py-2 border rounded-lg font-black" />
            </div>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">비고</label>
            <textarea name="remarks" value={formData.remarks} onChange={handleChange} rows={2} className="w-full px-3 py-2 border rounded-lg font-bold" placeholder="추가 참고사항"></textarea>
          </div>

          <button type="submit" className="w-full py-4 bg-indigo-600 text-white font-black rounded-xl shadow-lg hover:bg-indigo-700 transition-all uppercase tracking-widest text-sm mt-4">
            등록 완료
          </button>
        </form>
      </div>
    </div>
  );
};

export default AddItemModal;

import React, { useState, useMemo, useEffect } from 'react';
import type { Item, Transaction } from '../types';
import { CloseIcon, ArrowUpIcon, ArrowDownIcon, EditIcon, CheckIcon, BoxIcon, TrashIcon, DownloadIcon, PlusIcon } from './icons';

interface ItemDetailModalProps {
  item: Item;
  authRole: 'admin' | 'product_only';
  allUsedSerials: string[];
  existingCodes: string[];
  onAddTransaction: (itemId: string, transaction: Omit<Transaction, 'id'>) => void;
  onUpdateTransaction: (itemId: string, transactionId: string, updatedData: Partial<Transaction>) => void;
  onDeleteTransaction: (itemId: string, transactionId: string) => void;
  onUpdateItem: (itemId: string, updatedData: Partial<Item>) => void;
  onClose: () => void;
}

const ADMIN_PASSWORD = '0000';
const PRODUCT_ONLY_PASSWORD = '1111';

const ItemDetailModal: React.FC<ItemDetailModalProps> = ({ 
  item, authRole, allUsedSerials, existingCodes, onAddTransaction, onUpdateTransaction, onDeleteTransaction, onUpdateItem, onClose 
}) => {
  const [transactionType, setTransactionType] = useState<'purchase' | 'release'>('purchase');
  const [quantity, setQuantity] = useState('');
  const [transRemarks, setTransRemarks] = useState('');
  const [serialNumber, setSerialNumber] = useState('');
  const [isEditing, setIsEditing] = useState(false);
  const [editingTransactionId, setEditingTransactionId] = useState<string | null>(null);
  const [transEditData, setTransEditData] = useState<Partial<Transaction>>({});
  const [showPasswordInput, setShowPasswordInput] = useState<{ type: 'item' | 'trans_save' | 'trans_delete'; targetId?: string; } | null>(null);
  const [password, setPassword] = useState('');
  const [editFormData, setEditFormData] = useState<Partial<Item>>({});

  useEffect(() => {
    setEditFormData({
      name: item.name, code: item.code, modelName: item.modelName, application: item.application,
      drawingNumber: item.drawingNumber, spec: item.spec || '', remarks: item.remarks, registrationDate: item.registrationDate
    });
  }, [item, isEditing]);

  const currentStock = useMemo(() => item.transactions.reduce((acc, t) => t.type === 'purchase' ? acc + t.quantity : acc - t.quantity, 0), [item.transactions]);

  const handleAddTransaction = (e: React.FormEvent) => {
    e.preventDefault();
    const count = parseInt(quantity, 10) || 0;
    if (count <= 0) return;
    if (transactionType === 'release' && count > currentStock) { alert('재고가 부족합니다.'); return; }

    onAddTransaction(item.id, { 
      type: transactionType, 
      quantity: count, 
      date: new Date().toISOString(), 
      remarks: transRemarks,
      serialNumber: item.type === 'product' ? serialNumber.toUpperCase() : '',
    });
    setQuantity(''); setTransRemarks(''); setSerialNumber('');
  };

  const handleActionConfirm = () => {
    const requiredPass = authRole === 'admin' ? ADMIN_PASSWORD : PRODUCT_ONLY_PASSWORD;
    if (password !== requiredPass) { alert('비밀번호 오류.'); return; }
    const currentAction = showPasswordInput; setPassword(''); setShowPasswordInput(null);
    if (currentAction?.type === 'item') onUpdateItem(item.id, editFormData), setIsEditing(false);
    else if (currentAction?.type === 'trans_save' && currentAction.targetId) onUpdateTransaction(item.id, currentAction.targetId, transEditData), setEditingTransactionId(null);
    else if (currentAction?.type === 'trans_delete' && currentAction.targetId) onDeleteTransaction(item.id, currentAction.targetId);
  };

  const handleSaveInfo = () => {
    if (!editFormData.name || !editFormData.code) return;
    setShowPasswordInput({ type: 'item' });
  };

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex justify-center items-center z-50 p-4 overflow-hidden">
      <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-6xl flex flex-col h-full max-h-[90vh] overflow-hidden animate-fade-in-up">
        {showPasswordInput && (
            <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-[60] flex items-center justify-center p-4">
                <div className="bg-white rounded-2xl p-8 max-w-xs w-full shadow-2xl border border-slate-100">
                    <h4 className="text-lg font-black text-slate-800 mb-4 text-center">권한 비밀번호</h4>
                    <input type="password" autoFocus value={password} onChange={(e) => setPassword(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleActionConfirm()} placeholder="PASSWORD" className="w-full px-4 py-3 border-2 border-slate-100 rounded-xl focus:border-indigo-500 outline-none mb-6 text-center text-2xl font-black tracking-widest" />
                    <div className="grid grid-cols-2 gap-3">
                        <button onClick={() => setShowPasswordInput(null)} className="py-2 bg-slate-100 text-slate-600 rounded-lg font-black uppercase text-[10px]">취소</button>
                        <button onClick={handleActionConfirm} className="py-2 bg-indigo-600 text-white rounded-lg font-black uppercase text-[10px]">확인</button>
                    </div>
                </div>
            </div>
        )}

        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight">{item.type === 'part' ? '부품' : '제품'} 상세 정보</h2>
          <div className="flex gap-2">
              <button onClick={() => isEditing ? handleSaveInfo() : setIsEditing(true)} className={`flex items-center gap-1.5 px-4 py-2 rounded-lg text-xs font-black transition-all ${isEditing ? 'bg-emerald-600 text-white' : 'bg-white text-indigo-600 border border-indigo-100'}`}>
                {isEditing ? <CheckIcon className="w-4 h-4" /> : <EditIcon className="w-4 h-4" />}
                <span>{isEditing ? '변경사항 저장' : '정보 수정'}</span>
              </button>
              {isEditing && <button onClick={() => setIsEditing(false)} className="px-4 py-2 bg-slate-100 text-slate-500 rounded-lg text-xs font-black">취소</button>}
              <button onClick={onClose} className="p-2 text-slate-400 hover:text-slate-800 ml-2"><CloseIcon className="w-6 h-6" /></button>
          </div>
        </div>

        <div className="flex-grow overflow-y-auto p-6 grid grid-cols-1 lg:grid-cols-4 gap-8">
          <div className="lg:col-span-1 space-y-6">
            <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100 space-y-4">
              {isEditing ? (
                <div className="space-y-4">
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">품명 / 제품명</label>
                    <input value={editFormData.name || ''} onChange={(e) => setEditFormData({...editFormData, name: e.target.value.toUpperCase()})} className="w-full px-3 py-2 border rounded-lg font-black text-sm" />
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">코드</label>
                    <input value={editFormData.code || ''} onChange={(e) => setEditFormData({...editFormData, code: e.target.value.toUpperCase()})} className="w-full px-3 py-2 border rounded-lg font-mono font-black text-indigo-600" />
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <div>
                      <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">기종</label>
                      <input value={editFormData.modelName || ''} onChange={(e) => setEditFormData({...editFormData, modelName: e.target.value})} className="w-full px-3 py-2 border rounded-lg text-xs font-bold" />
                    </div>
                    <div>
                      <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">도번</label>
                      <input value={editFormData.drawingNumber || ''} onChange={(e) => setEditFormData({...editFormData, drawingNumber: e.target.value})} className="w-full px-3 py-2 border rounded-lg font-mono text-xs" />
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 block mb-1">적용</label>
                    <input value={editFormData.application || ''} onChange={(e) => setEditFormData({...editFormData, application: e.target.value})} className="w-full px-3 py-2 border rounded-lg text-xs font-bold" />
                  </div>
                </div>
              ) : (
                <>
                  <div>
                    <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Product Info</p>
                    <h3 className="text-2xl font-black text-slate-800 break-all leading-tight">{item.name}</h3>
                  </div>
                  <div className="space-y-2 border-t pt-4">
                    <div className="flex justify-between text-xs"><span className="text-slate-400 font-bold">CODE</span><span className="font-mono font-black text-indigo-600">{item.code}</span></div>
                    <div className="flex justify-between text-xs"><span className="text-slate-400 font-bold">MODEL</span><span className="font-bold text-slate-600">{item.modelName || '-'}</span></div>
                    <div className="flex justify-between text-xs"><span className="text-slate-400 font-bold">DRAWING</span><span className="font-mono text-slate-600">{item.drawingNumber || '-'}</span></div>
                    <div className="flex justify-between text-xs"><span className="text-slate-400 font-bold">APP</span><span className="font-bold text-slate-600">{item.application || '-'}</span></div>
                  </div>
                </>
              )}
              <div className="pt-6 border-t border-slate-200">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Current Stock</p>
                <p className="text-4xl font-black text-slate-900 leading-none">{currentStock.toLocaleString()} <span className="text-sm text-slate-300 font-black">EA</span></p>
              </div>
            </div>

            {!isEditing && (
              <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-lg space-y-4">
                <h4 className="text-xs font-black uppercase flex items-center gap-1.5"><PlusIcon className="w-4 h-4"/> 입출고 등록</h4>
                <div className="flex p-1 bg-slate-50 rounded-lg">
                  <button onClick={() => setTransactionType('purchase')} className={`flex-1 py-1.5 text-[10px] font-black rounded-md ${transactionType === 'purchase' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>입고</button>
                  <button onClick={() => setTransactionType('release')} className={`flex-1 py-1.5 text-[10px] font-black rounded-md ${transactionType === 'release' ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400'}`}>출고</button>
                </div>
                <div className="space-y-3">
                  <input type="number" value={quantity} onChange={(e) => setQuantity(e.target.value)} placeholder="수량 입력" className="w-full px-3 py-2 border rounded-lg font-black text-sm outline-none focus:border-indigo-500" />
                  <input type="text" value={transRemarks} onChange={(e) => setTransRemarks(e.target.value)} placeholder="비고 / 사유" className="w-full px-3 py-2 border rounded-lg text-xs font-bold outline-none" />
                  <button onClick={handleAddTransaction} className={`w-full py-3 text-white text-xs font-black rounded-xl transition-all shadow-md ${transactionType === 'purchase' ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-rose-600 hover:bg-rose-700'}`}>데이터 등록</button>
                </div>
              </div>
            )}
          </div>

          <div className="lg:col-span-3 flex flex-col h-full min-h-[400px]">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest">수불 히스토리</h3>
            </div>
            <div className="flex-grow border rounded-2xl overflow-hidden bg-slate-50/50">
              <div className="h-full overflow-y-auto">
                <table className="w-full text-left text-xs">
                  <thead className="bg-white border-b text-[10px] font-black uppercase text-slate-400 sticky top-0">
                    <tr>
                      <th className="px-4 py-3">날짜</th>
                      <th className="px-4 py-3">구분</th>
                      <th className="px-4 py-3 text-right">수량</th>
                      <th className="px-4 py-3">비고</th>
                      <th className="px-4 py-3 text-center">관리</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y bg-white/50">
                    {item.transactions.length === 0 ? (
                      <tr><td colSpan={5} className="px-4 py-12 text-center text-slate-300 font-bold uppercase tracking-widest">내역이 없습니다</td></tr>
                    ) : (
                      [...item.transactions].reverse().map(t => (
                        <tr key={t.id} className="hover:bg-white group">
                          <td className="px-4 py-3">
                            <p className="font-bold text-slate-700">{new Date(t.date).toLocaleDateString()}</p>
                            <p className="text-[9px] text-slate-400">{new Date(t.date).toLocaleTimeString()}</p>
                          </td>
                          <td className="px-4 py-3">
                            <span className={`px-2 py-0.5 rounded text-[9px] font-black uppercase ${t.type === 'purchase' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                              {t.type === 'purchase' ? '입고' : '출고'}
                            </span>
                          </td>
                          <td className={`px-4 py-3 text-right font-black text-sm ${t.type === 'purchase' ? 'text-emerald-600' : 'text-rose-600'}`}>
                            {t.type === 'purchase' ? '+' : '-'}{t.quantity.toLocaleString()}
                          </td>
                          <td className="px-4 py-3 text-slate-500 font-bold">{t.remarks || '-'}</td>
                          <td className="px-4 py-3 text-center">
                            <button onClick={() => setShowPasswordInput({ type: 'trans_delete', targetId: t.id })} className="p-1.5 text-slate-300 hover:text-rose-600 opacity-0 group-hover:opacity-100 transition-all">
                              <TrashIcon className="w-4 h-4" />
                            </button>
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ItemDetailModal;
